#!/bin/bash
# generateChaincodes_spatial.sh — regenerates the 34 location-aware contracts
# with a real radio model: serving-cell selection, SINR, admission control
# and capacity accounting.
#
# Generated by scripts/gen-spatial-contracts.js — do not edit by hand.
#
# Run it from the repository root, exactly like the generateChaincodes_part*
# scripts, then upgrade the affected chaincodes.

set -e

# The generated Go lands beside the part5..10 scripts, in scripts/chaincode —
# that is where deploy_functions.sh looks for it. Anchoring to this script's
# own location rather than the current directory means it no longer matters
# where you run it from; running from the repository root used to put the
# contracts one level up, and deploy then reported "directory not found".
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
cd "$SCRIPT_DIR"

ALL_CONTRACTS=(
    "LocationBasedAntennaConfig"
    "LocationBasedAssignment"
    "LocationBasedBandwidth"
    "LocationBasedChannelAllocation"
    "LocationBasedCongestion"
    "LocationBasedConnection"
    "LocationBasedCoverage"
    "LocationBasedDynamicRouting"
    "LocationBasedEnergy"
    "LocationBasedFault"
    "LocationBasedInterference"
    "LocationBasedIoTAuthentication"
    "LocationBasedIoTBandwidth"
    "LocationBasedIoTConnection"
    "LocationBasedIoTFault"
    "LocationBasedIoTRegistration"
    "LocationBasedIoTResource"
    "LocationBasedIoTRevocation"
    "LocationBasedIoTSession"
    "LocationBasedIoTStatus"
    "LocationBasedLatency"
    "LocationBasedNetworkHealth"
    "LocationBasedNetworkLoad"
    "LocationBasedPowerManagement"
    "LocationBasedPriority"
    "LocationBasedQoS"
    "LocationBasedResourceAllocation"
    "LocationBasedRoaming"
    "LocationBasedSessionManagement"
    "LocationBasedSignalQuality"
    "LocationBasedSignalStrength"
    "LocationBasedStatus"
    "LocationBasedTraffic"
    "LocationBasedUserActivity"
)

# With no arguments every location-aware contract is regenerated. Named
# arguments narrow it down, which is what the replacement part1-4 scripts
# use so the README's generateChaincodes_part*.sh loop keeps working and
# stays order-independent.
if [ $# -gt 0 ]; then
    contracts=("$@")
    for want in "${contracts[@]}"; do
        found=0
        for have in "${ALL_CONTRACTS[@]}"; do
            [ "$want" = "$have" ] && found=1 && break
        done
        if [ "$found" = "0" ]; then
            echo "$want is not a location-aware contract — it is generated by generateChaincodes_part5..10.sh" >&2
            exit 1
        fi
    done
else
    contracts=("${ALL_CONTRACTS[@]}")
fi

for contract in "${contracts[@]}"; do
    mkdir -p chaincode/$contract
    case $contract in
        LocationBasedAntennaConfig)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedAntennaConfig struct {
    contractapi.Contract
}

// AntennaConfig records a cell reconfiguration: where the antenna now stands and
// what coverage that produces.
type AntennaConfig struct {
    AntennaID     string `json:"antennaID"`
    Config string `json:"config"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    CoverageM     int64  `json:"coverageRadiusM"`
    EdgeRssiMilli int64  `json:"edgeRssiMilliDbm"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedAntennaConfig) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// SetAntennaConfig moves a cell and records the coverage that results.
//
// This contract acts ON an antenna rather than being served BY one: the
// antenna is relocated to (x,y), the registry is updated so every later
// evaluation sees the new position, and the resulting coverage radius is
// computed from the propagation model.
//
// Note for benchmarking: updating the registry is inherent here, not
// optional as it is in the serving contracts. There are only eight cells,
// so several transactions in one block will touch the same record and all
// but one will be rejected with MVCC_READ_CONFLICT. That is not a defect —
// reconfiguring a cell is genuinely a serialised operation — but it means
// this contract measures contention rather than throughput. Benchmark it at
// a low rate, or read the rejection rate as the result.
func (s *LocationBasedAntennaConfig) SetAntennaConfig(ctx contractapi.TransactionContextInterface, antennaID, config, x, y, seed string) error {
    if antennaID == "" {
        return fmt.Errorf("antennaID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    if px < 0 || py < 0 || px > cfg.GridSizeM || py > cfg.GridSizeM {
        return fmt.Errorf("position (%d,%d) is outside the %d m grid", px, py, cfg.GridSizeM)
    }

    ab, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("antenna %s is not registered — call SeedNetwork first", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }

    a.X, a.Y = px, py
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }

    radius, edge := s.coverageRadius(&a, cfg)
    record := AntennaConfig{
        AntennaID:     antennaID,
        Config: config,
        X:             px,
        Y:             py,
        CoverageM:     radius,
        EdgeRssiMilli: edge,
        Timestamp:     txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaID, recordJSON)
}

// coverageRadius finds the furthest distance at which the cell still clears
// the noise floor by the SINR margin, by bisection over the path-loss curve.
func (s *LocationBasedAntennaConfig) coverageRadius(a *Antenna, cfg *NetworkConfig) (int64, int64) {
    noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
    target := noise + cfg.MinSinrMilliDb
    lo, hi := int64(1), cfg.GridSizeM*2
    for lo < hi {
        mid := (lo + hi + 1) / 2
        pl := PathLossMilliDb(mid, a.FreqMHz, cfg.PathLossExponentMilli)
        if RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, 0) >= target {
            lo = mid
        } else {
            hi = mid - 1
        }
    }
    pl := PathLossMilliDb(lo, a.FreqMHz, cfg.PathLossExponentMilli)
    return lo, RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl, 0)
}

func (s *LocationBasedAntennaConfig) QueryAsset(ctx contractapi.TransactionContextInterface, antennaID string) (*AntennaConfig, error) {
    assetJSON, err := ctx.GetStub().GetState(antennaID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", antennaID)
    }
    var asset AntennaConfig
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedAntennaConfig) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*AntennaConfig, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*AntennaConfig
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset AntennaConfig
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage reports whether a position falls inside the cell's radius.
func (s *LocationBasedAntennaConfig) ValidateCoverage(ctx contractapi.TransactionContextInterface, antennaID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, antennaID)
    if err != nil {
        return false, err
    }
    return asset.CoverageM > 0, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedAntennaConfig) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedAntennaConfig) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedAntennaConfig) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedAntennaConfig) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedAntennaConfig) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedAntennaConfig) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedAntennaConfig) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedAntennaConfig) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedAntennaConfig) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedAntennaConfig) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedAntennaConfig) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedAntennaConfig) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedAntennaConfig) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedAntennaConfig) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedAntennaConfig) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedAntennaConfig) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedAntennaConfig) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedAntennaConfig) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedAntennaConfig) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedAntennaConfig) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedAntennaConfig) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedAntennaConfig) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedAntennaConfig) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedAntennaConfig) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedAntennaConfig) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedAntennaConfig) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedAntennaConfig) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedAntennaConfig) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedAntennaConfig) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedAntennaConfig) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedAntennaConfig) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedAntennaConfig) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedAntennaConfig) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedAntennaConfig) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedAntennaConfig) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedAntennaConfig) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedAntennaConfig) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedAntennaConfig) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedAntennaConfig) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedAntennaConfig) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedAntennaConfig) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedAntennaConfig) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedAntennaConfig) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedAntennaConfig) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedAntennaConfig))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedAssignment)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedAssignment struct {
    contractapi.Contract
}

// Assignment is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Assignment struct {
    EntityID string `json:"entityID"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedAssignment) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignAntenna requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedAssignment) AssignAntenna(ctx contractapi.TransactionContextInterface, entityID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Assignment{
        EntityID: entityID,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedAssignment) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Assignment, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Assignment
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedAssignment) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Assignment, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Assignment
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Assignment
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedAssignment) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedAssignment) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedAssignment) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedAssignment) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedAssignment) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedAssignment) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedAssignment) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedAssignment) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedAssignment) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedAssignment) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedAssignment) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedAssignment) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedAssignment) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedAssignment) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedAssignment) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedAssignment) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedAssignment) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedAssignment) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedAssignment) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedAssignment) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedAssignment) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedAssignment) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedAssignment) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedAssignment) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedAssignment) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedAssignment) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedAssignment) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Assignment
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedAssignment) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedAssignment) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedAssignment) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedAssignment) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedAssignment) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedAssignment) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedAssignment) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedAssignment) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedAssignment) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedAssignment) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedAssignment) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedAssignment) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedAssignment) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedAssignment) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedAssignment) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedAssignment) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedAssignment) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedAssignment) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedAssignment) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedAssignment))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedBandwidth)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedBandwidth struct {
    contractapi.Contract
}

// Bandwidth is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Bandwidth struct {
    EntityID string `json:"entityID"`
    Bandwidth string `json:"bandwidth"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedBandwidth) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignBandwidth requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedBandwidth) AssignBandwidth(ctx contractapi.TransactionContextInterface, entityID, bandwidth, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Bandwidth{
        EntityID: entityID,
        Bandwidth: bandwidth,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedBandwidth) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Bandwidth, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Bandwidth
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedBandwidth) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Bandwidth, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Bandwidth
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Bandwidth
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedBandwidth) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedBandwidth) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedBandwidth) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedBandwidth) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedBandwidth) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedBandwidth) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedBandwidth) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedBandwidth) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedBandwidth) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedBandwidth) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedBandwidth) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedBandwidth) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedBandwidth) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedBandwidth) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedBandwidth) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedBandwidth) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedBandwidth) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedBandwidth) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedBandwidth) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedBandwidth) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedBandwidth) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedBandwidth) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedBandwidth) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedBandwidth) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedBandwidth) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedBandwidth) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedBandwidth) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Bandwidth
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedBandwidth) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedBandwidth) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedBandwidth) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedBandwidth) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedBandwidth) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedBandwidth) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedBandwidth) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedBandwidth) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedBandwidth) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedBandwidth) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedBandwidth) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedBandwidth) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedBandwidth) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedBandwidth) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedBandwidth) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedBandwidth) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedBandwidth) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedBandwidth) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedBandwidth) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedBandwidth))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedChannelAllocation)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedChannelAllocation struct {
    contractapi.Contract
}

// ChannelAllocation is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type ChannelAllocation struct {
    EntityID string `json:"entityID"`
    ChannelID string `json:"channelID"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedChannelAllocation) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateChannel requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedChannelAllocation) AllocateChannel(ctx contractapi.TransactionContextInterface, entityID, channelID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := ChannelAllocation{
        EntityID: entityID,
        ChannelID: channelID,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedChannelAllocation) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*ChannelAllocation, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset ChannelAllocation
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedChannelAllocation) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*ChannelAllocation, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*ChannelAllocation
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset ChannelAllocation
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedChannelAllocation) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedChannelAllocation) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedChannelAllocation) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedChannelAllocation) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedChannelAllocation) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedChannelAllocation) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedChannelAllocation) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedChannelAllocation) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedChannelAllocation) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedChannelAllocation) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedChannelAllocation) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedChannelAllocation) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedChannelAllocation) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedChannelAllocation) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedChannelAllocation) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedChannelAllocation) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedChannelAllocation) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedChannelAllocation) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedChannelAllocation) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedChannelAllocation) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedChannelAllocation) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedChannelAllocation) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedChannelAllocation) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedChannelAllocation) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedChannelAllocation) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedChannelAllocation) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedChannelAllocation) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec ChannelAllocation
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedChannelAllocation) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedChannelAllocation) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedChannelAllocation) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedChannelAllocation) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedChannelAllocation) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedChannelAllocation) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedChannelAllocation) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedChannelAllocation) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedChannelAllocation) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedChannelAllocation) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedChannelAllocation) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedChannelAllocation) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedChannelAllocation) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedChannelAllocation) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedChannelAllocation) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedChannelAllocation) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedChannelAllocation) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedChannelAllocation) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedChannelAllocation) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedChannelAllocation))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedCongestion)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedCongestion struct {
    contractapi.Contract
}

// Congestion is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Congestion struct {
    EntityID string `json:"entityID"`
    Congestion string `json:"congestion"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedCongestion) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordCongestion requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedCongestion) RecordCongestion(ctx contractapi.TransactionContextInterface, entityID, congestion, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Congestion{
        EntityID: entityID,
        Congestion: congestion,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedCongestion) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Congestion, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Congestion
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedCongestion) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Congestion, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Congestion
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Congestion
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedCongestion) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedCongestion) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedCongestion) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedCongestion) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedCongestion) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedCongestion) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedCongestion) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedCongestion) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedCongestion) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedCongestion) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedCongestion) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedCongestion) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedCongestion) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedCongestion) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedCongestion) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedCongestion) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedCongestion) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedCongestion) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedCongestion) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedCongestion) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedCongestion) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedCongestion) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedCongestion) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedCongestion) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedCongestion) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedCongestion) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedCongestion) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Congestion
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedCongestion) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedCongestion) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedCongestion) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedCongestion) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedCongestion) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedCongestion) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedCongestion) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedCongestion) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedCongestion) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedCongestion) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedCongestion) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedCongestion) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedCongestion) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedCongestion) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedCongestion) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedCongestion) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedCongestion) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedCongestion) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedCongestion) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedCongestion))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedConnection)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedConnection struct {
    contractapi.Contract
}

// Connection is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Connection struct {
    EntityID string `json:"entityID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedConnection) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ConnectEntity requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedConnection) ConnectEntity(ctx contractapi.TransactionContextInterface, entityID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Connection{
        EntityID: entityID,
        Status: "",
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedConnection) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Connection, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Connection
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedConnection) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Connection, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Connection
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Connection
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedConnection) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedConnection) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedConnection) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedConnection) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedConnection) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedConnection) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedConnection) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedConnection) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedConnection) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedConnection) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedConnection) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedConnection) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedConnection) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedConnection) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedConnection) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedConnection) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedConnection) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedConnection) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedConnection) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedConnection) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedConnection) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedConnection) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedConnection) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedConnection) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedConnection) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedConnection) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedConnection) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Connection
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedConnection) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedConnection) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedConnection) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedConnection) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedConnection) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedConnection) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedConnection) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedConnection) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedConnection) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedConnection) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedConnection) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedConnection) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedConnection) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedConnection) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedConnection) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedConnection) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedConnection) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedConnection) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedConnection) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedConnection))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedCoverage)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedCoverage struct {
    contractapi.Contract
}

// CoverageRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type CoverageRecord struct {
    EntityID string `json:"entityID"`
    Coverage string `json:"coverage"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedCoverage) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordCoverage requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedCoverage) RecordCoverage(ctx contractapi.TransactionContextInterface, entityID, coverage, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := CoverageRecord{
        EntityID: entityID,
        Coverage: coverage,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedCoverage) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*CoverageRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset CoverageRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedCoverage) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*CoverageRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*CoverageRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset CoverageRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedCoverage) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedCoverage) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedCoverage) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedCoverage) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedCoverage) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedCoverage) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedCoverage) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedCoverage) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedCoverage) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedCoverage) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedCoverage) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedCoverage) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedCoverage) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedCoverage) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedCoverage) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedCoverage) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedCoverage) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedCoverage) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedCoverage) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedCoverage) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedCoverage) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedCoverage) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedCoverage) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedCoverage) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedCoverage) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedCoverage) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedCoverage) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec CoverageRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedCoverage) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedCoverage) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedCoverage) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedCoverage) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedCoverage) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedCoverage) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedCoverage) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedCoverage) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedCoverage) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedCoverage) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedCoverage) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedCoverage) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedCoverage) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedCoverage) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedCoverage) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedCoverage) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedCoverage) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedCoverage) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedCoverage) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedCoverage))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedDynamicRouting)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedDynamicRouting struct {
    contractapi.Contract
}

// DynamicRouting is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type DynamicRouting struct {
    EntityID string `json:"entityID"`
    Route string `json:"route"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedDynamicRouting) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// SetDynamicRoute requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedDynamicRouting) SetDynamicRoute(ctx contractapi.TransactionContextInterface, entityID, route, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := DynamicRouting{
        EntityID: entityID,
        Route: route,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedDynamicRouting) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*DynamicRouting, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset DynamicRouting
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedDynamicRouting) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*DynamicRouting, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*DynamicRouting
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset DynamicRouting
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedDynamicRouting) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedDynamicRouting) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedDynamicRouting) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedDynamicRouting) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedDynamicRouting) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedDynamicRouting) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedDynamicRouting) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedDynamicRouting) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedDynamicRouting) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedDynamicRouting) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedDynamicRouting) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedDynamicRouting) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedDynamicRouting) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedDynamicRouting) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedDynamicRouting) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedDynamicRouting) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedDynamicRouting) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedDynamicRouting) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedDynamicRouting) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedDynamicRouting) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedDynamicRouting) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedDynamicRouting) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedDynamicRouting) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedDynamicRouting) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedDynamicRouting) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedDynamicRouting) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedDynamicRouting) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec DynamicRouting
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedDynamicRouting) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedDynamicRouting) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedDynamicRouting) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedDynamicRouting) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedDynamicRouting) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedDynamicRouting) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedDynamicRouting) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedDynamicRouting) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedDynamicRouting) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedDynamicRouting) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedDynamicRouting) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedDynamicRouting) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedDynamicRouting) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedDynamicRouting) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedDynamicRouting) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedDynamicRouting) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedDynamicRouting) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedDynamicRouting) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedDynamicRouting) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedDynamicRouting))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedEnergy)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedEnergy struct {
    contractapi.Contract
}

// EnergyRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type EnergyRecord struct {
    EntityID string `json:"entityID"`
    Energy string `json:"energy"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedEnergy) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordEnergy requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedEnergy) RecordEnergy(ctx contractapi.TransactionContextInterface, entityID, energy, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := EnergyRecord{
        EntityID: entityID,
        Energy: energy,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedEnergy) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset EnergyRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedEnergy) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*EnergyRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*EnergyRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset EnergyRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedEnergy) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedEnergy) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedEnergy) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedEnergy) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedEnergy) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedEnergy) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedEnergy) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedEnergy) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedEnergy) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedEnergy) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedEnergy) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedEnergy) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedEnergy) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedEnergy) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedEnergy) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedEnergy) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedEnergy) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedEnergy) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedEnergy) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedEnergy) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedEnergy) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedEnergy) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedEnergy) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedEnergy) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedEnergy) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedEnergy) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedEnergy) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec EnergyRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedEnergy) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedEnergy) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedEnergy) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedEnergy) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedEnergy) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedEnergy) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedEnergy) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedEnergy) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedEnergy) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedEnergy) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedEnergy) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedEnergy) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedEnergy) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedEnergy) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedEnergy) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedEnergy) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedEnergy) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedEnergy) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedEnergy) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedEnergy))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedFault)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedFault struct {
    contractapi.Contract
}

// Fault is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Fault struct {
    EntityID string `json:"entityID"`
    FaultType string `json:"faultType"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedFault) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ReportFault requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedFault) ReportFault(ctx contractapi.TransactionContextInterface, entityID, faultType, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Fault{
        EntityID: entityID,
        FaultType: faultType,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedFault) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Fault, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Fault
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedFault) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Fault, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Fault
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Fault
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedFault) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedFault) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedFault) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedFault) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedFault) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedFault) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedFault) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedFault) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedFault) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedFault) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedFault) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedFault) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedFault) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedFault) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedFault) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedFault) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedFault) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedFault) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedFault) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedFault) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedFault) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedFault) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedFault) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedFault) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedFault) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedFault) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedFault) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Fault
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedFault) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedFault) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedFault) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedFault) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedFault) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedFault) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedFault) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedFault) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedFault) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedFault) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedFault) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedFault) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedFault) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedFault) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedFault) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedFault) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedFault) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedFault) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedFault) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedFault))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedInterference)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedInterference struct {
    contractapi.Contract
}

// InterferenceRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type InterferenceRecord struct {
    EntityID string `json:"entityID"`
    InterferenceLevel string `json:"interferenceLevel"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedInterference) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordInterference requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedInterference) RecordInterference(ctx contractapi.TransactionContextInterface, entityID, interferenceLevel, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := InterferenceRecord{
        EntityID: entityID,
        InterferenceLevel: interferenceLevel,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedInterference) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*InterferenceRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset InterferenceRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedInterference) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*InterferenceRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*InterferenceRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset InterferenceRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedInterference) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedInterference) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedInterference) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedInterference) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedInterference) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedInterference) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedInterference) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedInterference) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedInterference) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedInterference) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedInterference) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedInterference) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedInterference) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedInterference) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedInterference) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedInterference) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedInterference) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedInterference) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedInterference) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedInterference) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedInterference) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedInterference) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedInterference) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedInterference) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedInterference) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedInterference) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedInterference) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec InterferenceRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedInterference) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedInterference) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedInterference) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedInterference) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedInterference) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedInterference) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedInterference) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedInterference) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedInterference) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedInterference) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedInterference) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedInterference) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedInterference) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedInterference) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedInterference) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedInterference) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedInterference) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedInterference) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedInterference) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedInterference))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTAuthentication)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTAuthentication struct {
    contractapi.Contract
}

// IoTAuthentication is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTAuthentication struct {
    DeviceID string `json:"deviceID"`
    Token string `json:"token"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTAuthentication) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AuthenticateIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTAuthentication) AuthenticateIoT(ctx contractapi.TransactionContextInterface, deviceID, token, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTAuthentication{
        DeviceID: deviceID,
        Token: token,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTAuthentication) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTAuthentication, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTAuthentication
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTAuthentication) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTAuthentication, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTAuthentication
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTAuthentication
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTAuthentication) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTAuthentication) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTAuthentication) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTAuthentication) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTAuthentication) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTAuthentication) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTAuthentication) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTAuthentication) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTAuthentication) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTAuthentication) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTAuthentication) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTAuthentication) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTAuthentication) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTAuthentication) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTAuthentication) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTAuthentication) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTAuthentication) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTAuthentication) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTAuthentication) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTAuthentication) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTAuthentication) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTAuthentication) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTAuthentication) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTAuthentication) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTAuthentication) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTAuthentication) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTAuthentication) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTAuthentication
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTAuthentication) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTAuthentication) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTAuthentication) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTAuthentication) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTAuthentication) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTAuthentication) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTAuthentication) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTAuthentication) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTAuthentication) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTAuthentication) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTAuthentication) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTAuthentication) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTAuthentication) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTAuthentication) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTAuthentication) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTAuthentication) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTAuthentication) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTAuthentication) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTAuthentication) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTAuthentication))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTBandwidth)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTBandwidth struct {
    contractapi.Contract
}

// IoTBandwidth is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTBandwidth struct {
    DeviceID string `json:"deviceID"`
    Bandwidth string `json:"bandwidth"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTBandwidth) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateIoTBandwidth requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTBandwidth) AllocateIoTBandwidth(ctx contractapi.TransactionContextInterface, deviceID, bandwidth, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTBandwidth{
        DeviceID: deviceID,
        Bandwidth: bandwidth,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTBandwidth) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTBandwidth, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTBandwidth
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTBandwidth) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTBandwidth, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTBandwidth
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTBandwidth
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTBandwidth) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTBandwidth) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTBandwidth) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTBandwidth) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTBandwidth) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTBandwidth) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTBandwidth) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTBandwidth) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTBandwidth) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTBandwidth) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTBandwidth) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTBandwidth) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTBandwidth) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTBandwidth) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTBandwidth) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTBandwidth) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTBandwidth) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTBandwidth) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTBandwidth) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTBandwidth) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTBandwidth) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTBandwidth) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTBandwidth) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTBandwidth) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTBandwidth) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTBandwidth) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTBandwidth) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTBandwidth
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTBandwidth) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTBandwidth) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTBandwidth) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTBandwidth) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTBandwidth) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTBandwidth) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTBandwidth) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTBandwidth) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTBandwidth) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTBandwidth) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTBandwidth) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTBandwidth) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTBandwidth) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTBandwidth) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTBandwidth) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTBandwidth) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTBandwidth) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTBandwidth) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTBandwidth) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTBandwidth))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTConnection)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTConnection struct {
    contractapi.Contract
}

// IoTConnection is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTConnection struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTConnection) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ConnectIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTConnection) ConnectIoT(ctx contractapi.TransactionContextInterface, deviceID, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTConnection{
        DeviceID: deviceID,
        Status: "",
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTConnection) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTConnection, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTConnection
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTConnection) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTConnection, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTConnection
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTConnection
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTConnection) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTConnection) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTConnection) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTConnection) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTConnection) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTConnection) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTConnection) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTConnection) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTConnection) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTConnection) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTConnection) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTConnection) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTConnection) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTConnection) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTConnection) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTConnection) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTConnection) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTConnection) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTConnection) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTConnection) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTConnection) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTConnection) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTConnection) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTConnection) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTConnection) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTConnection) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTConnection) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTConnection
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTConnection) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTConnection) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTConnection) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTConnection) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTConnection) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTConnection) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTConnection) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTConnection) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTConnection) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTConnection) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTConnection) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTConnection) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTConnection) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTConnection) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTConnection) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTConnection) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTConnection) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTConnection) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTConnection) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTConnection))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTFault)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTFault struct {
    contractapi.Contract
}

// IoTFault is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTFault struct {
    DeviceID string `json:"deviceID"`
    FaultType string `json:"faultType"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTFault) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ReportIoTFault requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTFault) ReportIoTFault(ctx contractapi.TransactionContextInterface, deviceID, faultType, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTFault{
        DeviceID: deviceID,
        FaultType: faultType,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTFault) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTFault, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTFault
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTFault) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTFault, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTFault
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTFault
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTFault) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTFault) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTFault) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTFault) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTFault) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTFault) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTFault) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTFault) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTFault) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTFault) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTFault) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTFault) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTFault) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTFault) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTFault) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTFault) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTFault) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTFault) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTFault) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTFault) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTFault) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTFault) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTFault) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTFault) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTFault) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTFault) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTFault) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTFault
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTFault) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTFault) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTFault) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTFault) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTFault) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTFault) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTFault) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTFault) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTFault) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTFault) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTFault) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTFault) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTFault) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTFault) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTFault) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTFault) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTFault) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTFault) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTFault) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTFault))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTRegistration)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTRegistration struct {
    contractapi.Contract
}

// IoTRegistration is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTRegistration struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTRegistration) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RegisterIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTRegistration) RegisterIoT(ctx contractapi.TransactionContextInterface, deviceID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTRegistration{
        DeviceID: deviceID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTRegistration) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTRegistration, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTRegistration
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTRegistration) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTRegistration, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTRegistration
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTRegistration
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTRegistration) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTRegistration) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTRegistration) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTRegistration) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTRegistration) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTRegistration) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTRegistration) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTRegistration) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTRegistration) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTRegistration) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTRegistration) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTRegistration) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTRegistration) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTRegistration) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTRegistration) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTRegistration) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTRegistration) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTRegistration) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTRegistration) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTRegistration) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTRegistration) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTRegistration) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTRegistration) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTRegistration) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTRegistration) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTRegistration) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTRegistration) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTRegistration
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTRegistration) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTRegistration) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTRegistration) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTRegistration) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTRegistration) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTRegistration) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTRegistration) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTRegistration) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTRegistration) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTRegistration) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTRegistration) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTRegistration) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTRegistration) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTRegistration) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTRegistration) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTRegistration) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTRegistration) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTRegistration) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTRegistration) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTRegistration))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTResource)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTResource struct {
    contractapi.Contract
}

// IoTResource is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTResource struct {
    DeviceID string `json:"deviceID"`
    ResourceID string `json:"resourceID"`
    Amount string `json:"amount"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTResource) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateIoTResource requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTResource) AllocateIoTResource(ctx contractapi.TransactionContextInterface, deviceID, resourceID, amount, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTResource{
        DeviceID: deviceID,
        ResourceID: resourceID,
        Amount: amount,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTResource) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTResource, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTResource
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTResource) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTResource, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTResource
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTResource
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTResource) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTResource) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTResource) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTResource) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTResource) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTResource) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTResource) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTResource) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTResource) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTResource) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTResource) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTResource) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTResource) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTResource) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTResource) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTResource) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTResource) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTResource) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTResource) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTResource) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTResource) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTResource) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTResource) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTResource) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTResource) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTResource) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTResource) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTResource
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTResource) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTResource) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTResource) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTResource) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTResource) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTResource) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTResource) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTResource) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTResource) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTResource) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTResource) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTResource) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTResource) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTResource) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTResource) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTResource) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTResource) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTResource) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTResource) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTResource))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTRevocation)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTRevocation struct {
    contractapi.Contract
}

// IoTRevocation is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTRevocation struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTRevocation) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RevokeIoT requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTRevocation) RevokeIoT(ctx contractapi.TransactionContextInterface, deviceID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTRevocation{
        DeviceID: deviceID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTRevocation) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTRevocation, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTRevocation
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTRevocation) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTRevocation, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTRevocation
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTRevocation
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTRevocation) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTRevocation) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTRevocation) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTRevocation) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTRevocation) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTRevocation) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTRevocation) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTRevocation) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTRevocation) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTRevocation) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTRevocation) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTRevocation) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTRevocation) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTRevocation) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTRevocation) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTRevocation) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTRevocation) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTRevocation) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTRevocation) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTRevocation) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTRevocation) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTRevocation) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTRevocation) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTRevocation) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTRevocation) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTRevocation) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTRevocation) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTRevocation
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTRevocation) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTRevocation) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTRevocation) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTRevocation) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTRevocation) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTRevocation) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTRevocation) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTRevocation) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTRevocation) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTRevocation) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTRevocation) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTRevocation) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTRevocation) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTRevocation) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTRevocation) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTRevocation) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTRevocation) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTRevocation) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTRevocation) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTRevocation))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTSession)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTSession struct {
    contractapi.Contract
}

// IoTSession is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTSession struct {
    DeviceID string `json:"deviceID"`
    SessionID string `json:"sessionID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTSession) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// StartIoTSession requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTSession) StartIoTSession(ctx contractapi.TransactionContextInterface, deviceID, sessionID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTSession{
        DeviceID: deviceID,
        SessionID: sessionID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTSession) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTSession, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTSession
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTSession) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTSession, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTSession
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTSession
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTSession) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTSession) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTSession) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTSession) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTSession) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTSession) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTSession) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTSession) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTSession) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTSession) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTSession) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTSession) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTSession) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTSession) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTSession) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTSession) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTSession) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTSession) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTSession) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTSession) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTSession) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTSession) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTSession) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTSession) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTSession) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTSession) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTSession) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTSession
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTSession) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTSession) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTSession) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTSession) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTSession) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTSession) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTSession) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTSession) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTSession) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTSession) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTSession) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTSession) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTSession) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTSession) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTSession) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTSession) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTSession) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTSession) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTSession) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTSession))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedIoTStatus)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedIoTStatus struct {
    contractapi.Contract
}

// IoTStatus is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type IoTStatus struct {
    DeviceID string `json:"deviceID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedIoTStatus) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// UpdateIoTStatus requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedIoTStatus) UpdateIoTStatus(ctx contractapi.TransactionContextInterface, deviceID, status, x, y, seed string) error {
    if deviceID == "" {
        return fmt.Errorf("deviceID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, deviceID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, deviceID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+deviceID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, deviceID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, deviceID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+deviceID, bb); berr != nil {
            return berr
        }
    }

    record := IoTStatus{
        DeviceID: deviceID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(deviceID, recordJSON)
}

func (s *LocationBasedIoTStatus) QueryAsset(ctx contractapi.TransactionContextInterface, deviceID string) (*IoTStatus, error) {
    assetJSON, err := ctx.GetStub().GetState(deviceID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", deviceID)
    }
    var asset IoTStatus
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedIoTStatus) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*IoTStatus, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*IoTStatus
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset IoTStatus
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedIoTStatus) ValidateCoverage(ctx contractapi.TransactionContextInterface, deviceID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, deviceID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedIoTStatus) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedIoTStatus) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedIoTStatus) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedIoTStatus) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedIoTStatus) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedIoTStatus) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedIoTStatus) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedIoTStatus) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedIoTStatus) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedIoTStatus) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedIoTStatus) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedIoTStatus) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedIoTStatus) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedIoTStatus) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedIoTStatus) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedIoTStatus) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedIoTStatus) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedIoTStatus) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedIoTStatus) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedIoTStatus) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedIoTStatus) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedIoTStatus) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedIoTStatus) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedIoTStatus) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedIoTStatus) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedIoTStatus) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec IoTStatus
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedIoTStatus) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedIoTStatus) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedIoTStatus) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedIoTStatus) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedIoTStatus) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedIoTStatus) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedIoTStatus) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedIoTStatus) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedIoTStatus) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedIoTStatus) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedIoTStatus) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedIoTStatus) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedIoTStatus) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedIoTStatus) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedIoTStatus) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedIoTStatus) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedIoTStatus) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedIoTStatus) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedIoTStatus) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedIoTStatus))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedLatency)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedLatency struct {
    contractapi.Contract
}

// Latency is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Latency struct {
    EntityID string `json:"entityID"`
    Latency string `json:"latency"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedLatency) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordLatency requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedLatency) RecordLatency(ctx contractapi.TransactionContextInterface, entityID, latency, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Latency{
        EntityID: entityID,
        Latency: latency,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedLatency) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Latency, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Latency
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedLatency) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Latency, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Latency
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Latency
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedLatency) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedLatency) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedLatency) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedLatency) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedLatency) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedLatency) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedLatency) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedLatency) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedLatency) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedLatency) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedLatency) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedLatency) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedLatency) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedLatency) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedLatency) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedLatency) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedLatency) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedLatency) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedLatency) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedLatency) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedLatency) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedLatency) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedLatency) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedLatency) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedLatency) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedLatency) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedLatency) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Latency
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedLatency) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedLatency) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedLatency) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedLatency) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedLatency) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedLatency) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedLatency) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedLatency) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedLatency) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedLatency) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedLatency) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedLatency) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedLatency) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedLatency) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedLatency) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedLatency) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedLatency) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedLatency) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedLatency) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedLatency))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedNetworkHealth)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedNetworkHealth struct {
    contractapi.Contract
}

// NetworkHealth is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type NetworkHealth struct {
    EntityID string `json:"entityID"`
    HealthStatus string `json:"healthStatus"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedNetworkHealth) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordNetworkHealth requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedNetworkHealth) RecordNetworkHealth(ctx contractapi.TransactionContextInterface, entityID, healthStatus, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := NetworkHealth{
        EntityID: entityID,
        HealthStatus: healthStatus,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedNetworkHealth) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*NetworkHealth, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset NetworkHealth
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedNetworkHealth) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*NetworkHealth, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*NetworkHealth
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset NetworkHealth
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedNetworkHealth) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedNetworkHealth) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedNetworkHealth) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedNetworkHealth) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedNetworkHealth) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedNetworkHealth) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedNetworkHealth) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedNetworkHealth) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedNetworkHealth) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedNetworkHealth) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedNetworkHealth) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedNetworkHealth) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedNetworkHealth) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedNetworkHealth) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedNetworkHealth) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedNetworkHealth) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedNetworkHealth) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedNetworkHealth) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedNetworkHealth) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedNetworkHealth) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedNetworkHealth) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedNetworkHealth) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedNetworkHealth) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedNetworkHealth) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedNetworkHealth) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedNetworkHealth) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedNetworkHealth) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec NetworkHealth
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedNetworkHealth) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedNetworkHealth) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedNetworkHealth) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedNetworkHealth) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedNetworkHealth) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedNetworkHealth) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedNetworkHealth) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedNetworkHealth) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedNetworkHealth) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedNetworkHealth) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedNetworkHealth) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedNetworkHealth) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedNetworkHealth) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedNetworkHealth) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedNetworkHealth) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedNetworkHealth) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedNetworkHealth) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedNetworkHealth) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedNetworkHealth) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedNetworkHealth))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedNetworkLoad)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedNetworkLoad struct {
    contractapi.Contract
}

// NetworkLoadRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type NetworkLoadRecord struct {
    EntityID string `json:"entityID"`
    Load string `json:"load"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedNetworkLoad) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordNetworkLoad requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedNetworkLoad) RecordNetworkLoad(ctx contractapi.TransactionContextInterface, entityID, load, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := NetworkLoadRecord{
        EntityID: entityID,
        Load: load,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedNetworkLoad) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*NetworkLoadRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset NetworkLoadRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedNetworkLoad) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*NetworkLoadRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*NetworkLoadRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset NetworkLoadRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedNetworkLoad) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedNetworkLoad) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedNetworkLoad) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedNetworkLoad) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedNetworkLoad) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedNetworkLoad) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedNetworkLoad) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedNetworkLoad) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedNetworkLoad) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedNetworkLoad) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedNetworkLoad) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedNetworkLoad) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedNetworkLoad) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedNetworkLoad) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedNetworkLoad) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedNetworkLoad) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedNetworkLoad) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedNetworkLoad) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedNetworkLoad) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedNetworkLoad) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedNetworkLoad) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedNetworkLoad) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedNetworkLoad) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedNetworkLoad) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedNetworkLoad) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedNetworkLoad) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedNetworkLoad) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec NetworkLoadRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedNetworkLoad) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedNetworkLoad) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedNetworkLoad) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedNetworkLoad) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedNetworkLoad) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedNetworkLoad) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedNetworkLoad) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedNetworkLoad) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedNetworkLoad) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedNetworkLoad) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedNetworkLoad) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedNetworkLoad) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedNetworkLoad) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedNetworkLoad) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedNetworkLoad) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedNetworkLoad) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedNetworkLoad) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedNetworkLoad) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedNetworkLoad) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedNetworkLoad))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedPowerManagement)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedPowerManagement struct {
    contractapi.Contract
}

// PowerManagement is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type PowerManagement struct {
    EntityID string `json:"entityID"`
    PowerLevel string `json:"powerLevel"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedPowerManagement) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// SetPowerLevel requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedPowerManagement) SetPowerLevel(ctx contractapi.TransactionContextInterface, entityID, powerLevel, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := PowerManagement{
        EntityID: entityID,
        PowerLevel: powerLevel,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedPowerManagement) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*PowerManagement, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset PowerManagement
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedPowerManagement) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*PowerManagement, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*PowerManagement
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset PowerManagement
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedPowerManagement) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedPowerManagement) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedPowerManagement) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedPowerManagement) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedPowerManagement) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedPowerManagement) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedPowerManagement) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedPowerManagement) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedPowerManagement) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedPowerManagement) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedPowerManagement) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedPowerManagement) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedPowerManagement) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedPowerManagement) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedPowerManagement) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedPowerManagement) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedPowerManagement) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedPowerManagement) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedPowerManagement) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedPowerManagement) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedPowerManagement) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedPowerManagement) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedPowerManagement) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedPowerManagement) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedPowerManagement) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedPowerManagement) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedPowerManagement) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec PowerManagement
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedPowerManagement) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedPowerManagement) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedPowerManagement) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedPowerManagement) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedPowerManagement) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedPowerManagement) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedPowerManagement) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedPowerManagement) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedPowerManagement) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedPowerManagement) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedPowerManagement) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedPowerManagement) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedPowerManagement) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedPowerManagement) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedPowerManagement) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedPowerManagement) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedPowerManagement) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedPowerManagement) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedPowerManagement) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedPowerManagement))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedPriority)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedPriority struct {
    contractapi.Contract
}

// Priority is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Priority struct {
    EntityID string `json:"entityID"`
    Priority string `json:"priority"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedPriority) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignPriority requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedPriority) AssignPriority(ctx contractapi.TransactionContextInterface, entityID, priority, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Priority{
        EntityID: entityID,
        Priority: priority,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedPriority) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Priority, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Priority
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedPriority) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Priority, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Priority
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Priority
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedPriority) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedPriority) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedPriority) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedPriority) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedPriority) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedPriority) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedPriority) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedPriority) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedPriority) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedPriority) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedPriority) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedPriority) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedPriority) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedPriority) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedPriority) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedPriority) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedPriority) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedPriority) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedPriority) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedPriority) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedPriority) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedPriority) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedPriority) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedPriority) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedPriority) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedPriority) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedPriority) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Priority
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedPriority) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedPriority) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedPriority) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedPriority) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedPriority) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedPriority) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedPriority) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedPriority) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedPriority) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedPriority) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedPriority) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedPriority) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedPriority) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedPriority) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedPriority) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedPriority) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedPriority) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedPriority) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedPriority) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedPriority))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedQoS)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedQoS struct {
    contractapi.Contract
}

// QoS is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type QoS struct {
    EntityID string `json:"entityID"`
    QoSLevel string `json:"qosLevel"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedQoS) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AssignQoS requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedQoS) AssignQoS(ctx contractapi.TransactionContextInterface, entityID, qosLevel, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := QoS{
        EntityID: entityID,
        QoSLevel: qosLevel,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedQoS) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*QoS, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset QoS
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedQoS) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*QoS, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*QoS
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset QoS
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedQoS) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedQoS) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedQoS) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedQoS) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedQoS) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedQoS) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedQoS) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedQoS) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedQoS) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedQoS) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedQoS) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedQoS) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedQoS) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedQoS) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedQoS) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedQoS) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedQoS) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedQoS) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedQoS) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedQoS) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedQoS) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedQoS) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedQoS) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedQoS) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedQoS) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedQoS) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedQoS) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec QoS
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedQoS) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedQoS) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedQoS) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedQoS) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedQoS) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedQoS) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedQoS) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedQoS) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedQoS) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedQoS) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedQoS) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedQoS) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedQoS) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedQoS) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedQoS) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedQoS) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedQoS) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedQoS) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedQoS) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedQoS))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedResourceAllocation)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedResourceAllocation struct {
    contractapi.Contract
}

// ResourceAllocation is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type ResourceAllocation struct {
    EntityID string `json:"entityID"`
    ResourceID string `json:"resourceID"`
    Amount string `json:"amount"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedResourceAllocation) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// AllocateResource requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedResourceAllocation) AllocateResource(ctx contractapi.TransactionContextInterface, entityID, resourceID, amount, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := ResourceAllocation{
        EntityID: entityID,
        ResourceID: resourceID,
        Amount: amount,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedResourceAllocation) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*ResourceAllocation, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset ResourceAllocation
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedResourceAllocation) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*ResourceAllocation, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*ResourceAllocation
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset ResourceAllocation
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedResourceAllocation) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedResourceAllocation) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedResourceAllocation) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedResourceAllocation) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedResourceAllocation) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedResourceAllocation) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedResourceAllocation) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedResourceAllocation) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedResourceAllocation) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedResourceAllocation) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedResourceAllocation) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedResourceAllocation) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedResourceAllocation) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedResourceAllocation) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedResourceAllocation) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedResourceAllocation) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedResourceAllocation) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedResourceAllocation) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedResourceAllocation) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedResourceAllocation) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedResourceAllocation) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedResourceAllocation) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedResourceAllocation) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedResourceAllocation) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedResourceAllocation) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedResourceAllocation) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedResourceAllocation) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec ResourceAllocation
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedResourceAllocation) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedResourceAllocation) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedResourceAllocation) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedResourceAllocation) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedResourceAllocation) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedResourceAllocation) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedResourceAllocation) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedResourceAllocation) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedResourceAllocation) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedResourceAllocation) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedResourceAllocation) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedResourceAllocation) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedResourceAllocation) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedResourceAllocation) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedResourceAllocation) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedResourceAllocation) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedResourceAllocation) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedResourceAllocation) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedResourceAllocation) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedResourceAllocation))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedRoaming)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedRoaming struct {
    contractapi.Contract
}

// RoamingRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type RoamingRecord struct {
    EntityID string `json:"entityID"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedRoaming) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// PerformRoaming requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedRoaming) PerformRoaming(ctx contractapi.TransactionContextInterface, entityID, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := RoamingRecord{
        EntityID: entityID,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedRoaming) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*RoamingRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset RoamingRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedRoaming) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*RoamingRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*RoamingRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset RoamingRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedRoaming) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedRoaming) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedRoaming) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedRoaming) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedRoaming) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedRoaming) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedRoaming) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedRoaming) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedRoaming) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedRoaming) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedRoaming) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedRoaming) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedRoaming) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedRoaming) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedRoaming) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedRoaming) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedRoaming) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedRoaming) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedRoaming) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedRoaming) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedRoaming) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedRoaming) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedRoaming) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedRoaming) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedRoaming) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedRoaming) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedRoaming) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec RoamingRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedRoaming) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedRoaming) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedRoaming) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedRoaming) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedRoaming) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedRoaming) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedRoaming) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedRoaming) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedRoaming) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedRoaming) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedRoaming) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedRoaming) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedRoaming) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedRoaming) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedRoaming) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedRoaming) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedRoaming) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedRoaming) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedRoaming) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedRoaming))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedSessionManagement)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedSessionManagement struct {
    contractapi.Contract
}

// SessionManagement is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type SessionManagement struct {
    EntityID string `json:"entityID"`
    SessionID string `json:"sessionID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedSessionManagement) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// ManageSession requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedSessionManagement) ManageSession(ctx contractapi.TransactionContextInterface, entityID, sessionID, status, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := SessionManagement{
        EntityID: entityID,
        SessionID: sessionID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedSessionManagement) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*SessionManagement, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset SessionManagement
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedSessionManagement) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*SessionManagement, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*SessionManagement
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset SessionManagement
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedSessionManagement) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedSessionManagement) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedSessionManagement) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedSessionManagement) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedSessionManagement) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedSessionManagement) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedSessionManagement) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedSessionManagement) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedSessionManagement) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedSessionManagement) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedSessionManagement) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedSessionManagement) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedSessionManagement) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedSessionManagement) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedSessionManagement) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedSessionManagement) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedSessionManagement) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedSessionManagement) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedSessionManagement) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedSessionManagement) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedSessionManagement) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedSessionManagement) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedSessionManagement) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedSessionManagement) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedSessionManagement) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedSessionManagement) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedSessionManagement) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec SessionManagement
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedSessionManagement) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedSessionManagement) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedSessionManagement) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedSessionManagement) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedSessionManagement) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedSessionManagement) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedSessionManagement) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedSessionManagement) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedSessionManagement) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedSessionManagement) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedSessionManagement) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedSessionManagement) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedSessionManagement) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedSessionManagement) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedSessionManagement) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedSessionManagement) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedSessionManagement) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedSessionManagement) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedSessionManagement) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedSessionManagement))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedSignalQuality)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedSignalQuality struct {
    contractapi.Contract
}

// SignalQuality is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type SignalQuality struct {
    EntityID string `json:"entityID"`
    SignalQuality string `json:"signalQuality"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedSignalQuality) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordSignalQuality requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedSignalQuality) RecordSignalQuality(ctx contractapi.TransactionContextInterface, entityID, signalQuality, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := SignalQuality{
        EntityID: entityID,
        SignalQuality: signalQuality,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedSignalQuality) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*SignalQuality, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset SignalQuality
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedSignalQuality) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*SignalQuality, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*SignalQuality
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset SignalQuality
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedSignalQuality) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedSignalQuality) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedSignalQuality) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedSignalQuality) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedSignalQuality) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedSignalQuality) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedSignalQuality) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedSignalQuality) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedSignalQuality) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedSignalQuality) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedSignalQuality) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedSignalQuality) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedSignalQuality) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedSignalQuality) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedSignalQuality) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedSignalQuality) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedSignalQuality) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedSignalQuality) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedSignalQuality) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedSignalQuality) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedSignalQuality) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedSignalQuality) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedSignalQuality) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedSignalQuality) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedSignalQuality) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedSignalQuality) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedSignalQuality) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec SignalQuality
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedSignalQuality) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedSignalQuality) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedSignalQuality) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedSignalQuality) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedSignalQuality) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedSignalQuality) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedSignalQuality) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedSignalQuality) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedSignalQuality) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedSignalQuality) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedSignalQuality) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedSignalQuality) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedSignalQuality) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedSignalQuality) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedSignalQuality) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedSignalQuality) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedSignalQuality) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedSignalQuality) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedSignalQuality) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedSignalQuality))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedSignalStrength)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedSignalStrength struct {
    contractapi.Contract
}

// SignalStrengthRecord is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type SignalStrengthRecord struct {
    EntityID string `json:"entityID"`
    Signal string `json:"signal"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedSignalStrength) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordSignalStrength requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedSignalStrength) RecordSignalStrength(ctx contractapi.TransactionContextInterface, entityID, signal, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := SignalStrengthRecord{
        EntityID: entityID,
        Signal: signal,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedSignalStrength) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*SignalStrengthRecord, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset SignalStrengthRecord
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedSignalStrength) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*SignalStrengthRecord, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*SignalStrengthRecord
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset SignalStrengthRecord
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedSignalStrength) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedSignalStrength) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedSignalStrength) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedSignalStrength) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedSignalStrength) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedSignalStrength) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedSignalStrength) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedSignalStrength) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedSignalStrength) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedSignalStrength) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedSignalStrength) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedSignalStrength) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedSignalStrength) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedSignalStrength) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedSignalStrength) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedSignalStrength) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedSignalStrength) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedSignalStrength) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedSignalStrength) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedSignalStrength) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedSignalStrength) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedSignalStrength) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedSignalStrength) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedSignalStrength) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedSignalStrength) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedSignalStrength) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedSignalStrength) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec SignalStrengthRecord
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedSignalStrength) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedSignalStrength) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedSignalStrength) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedSignalStrength) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedSignalStrength) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedSignalStrength) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedSignalStrength) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedSignalStrength) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedSignalStrength) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedSignalStrength) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedSignalStrength) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedSignalStrength) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedSignalStrength) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedSignalStrength) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedSignalStrength) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedSignalStrength) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedSignalStrength) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedSignalStrength) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedSignalStrength) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedSignalStrength))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedStatus)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedStatus struct {
    contractapi.Contract
}

// Status is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Status struct {
    EntityID string `json:"entityID"`
    Status string `json:"status"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedStatus) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// UpdateStatus requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedStatus) UpdateStatus(ctx contractapi.TransactionContextInterface, entityID, status, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Status{
        EntityID: entityID,
        Status: status,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedStatus) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Status, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Status
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedStatus) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Status, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Status
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Status
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedStatus) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedStatus) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedStatus) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedStatus) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedStatus) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedStatus) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedStatus) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedStatus) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedStatus) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedStatus) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedStatus) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedStatus) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedStatus) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedStatus) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedStatus) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedStatus) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedStatus) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedStatus) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedStatus) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedStatus) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedStatus) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedStatus) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedStatus) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedStatus) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedStatus) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedStatus) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedStatus) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Status
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedStatus) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedStatus) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedStatus) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedStatus) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedStatus) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedStatus) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedStatus) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedStatus) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedStatus) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedStatus) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedStatus) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedStatus) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedStatus) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedStatus) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedStatus) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedStatus) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedStatus) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedStatus) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedStatus) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedStatus))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedTraffic)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedTraffic struct {
    contractapi.Contract
}

// Traffic is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type Traffic struct {
    EntityID string `json:"entityID"`
    Traffic string `json:"traffic"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedTraffic) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordTraffic requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedTraffic) RecordTraffic(ctx contractapi.TransactionContextInterface, entityID, traffic, x, y, seed string) error {
    if entityID == "" {
        return fmt.Errorf("entityID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, entityID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, entityID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+entityID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, entityID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, entityID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+entityID, bb); berr != nil {
            return berr
        }
    }

    record := Traffic{
        EntityID: entityID,
        Traffic: traffic,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(entityID, recordJSON)
}

func (s *LocationBasedTraffic) QueryAsset(ctx contractapi.TransactionContextInterface, entityID string) (*Traffic, error) {
    assetJSON, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", entityID)
    }
    var asset Traffic
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedTraffic) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*Traffic, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*Traffic
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset Traffic
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedTraffic) ValidateCoverage(ctx contractapi.TransactionContextInterface, entityID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, entityID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedTraffic) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedTraffic) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedTraffic) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedTraffic) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedTraffic) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedTraffic) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedTraffic) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedTraffic) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedTraffic) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedTraffic) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedTraffic) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedTraffic) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedTraffic) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedTraffic) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedTraffic) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedTraffic) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedTraffic) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedTraffic) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedTraffic) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedTraffic) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedTraffic) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedTraffic) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedTraffic) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedTraffic) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedTraffic) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedTraffic) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec Traffic
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedTraffic) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedTraffic) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedTraffic) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedTraffic) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedTraffic) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedTraffic) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedTraffic) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedTraffic) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedTraffic) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedTraffic) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedTraffic) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedTraffic) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedTraffic) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedTraffic) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedTraffic) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedTraffic) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedTraffic) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedTraffic) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedTraffic) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedTraffic))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        LocationBasedUserActivity)
            cat > chaincode/$contract/chaincode.go <<'CHAINCODE_EOF'
package main

import (
    "encoding/json"
    "fmt"
    "strconv"
    "time"

    "github.com/hyperledger/fabric-contract-api-go/contractapi"
)

type LocationBasedUserActivity struct {
    contractapi.Contract
}

// UserActivity is what a successful admission writes: the domain fields the
// caller supplied, plus the radio outcome the contract computed.
type UserActivity struct {
    UserID string `json:"userID"`
    Activity string `json:"activity"`
    X             int64  `json:"x"`
    Y             int64  `json:"y"`
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    GrantedHz     int64  `json:"grantedHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Timestamp     string `json:"timestamp"`
}

func (s *LocationBasedUserActivity) Init(ctx contractapi.TransactionContextInterface) error {
    return nil
}

// RecordUserActivity requests service at a position.
//
// The caller no longer names an antenna — the contract picks the serving
// cell, checks coverage and capacity, and may refuse. On success the load
// it added is written back, so the next caller sees a fuller cell.
func (s *LocationBasedUserActivity) RecordUserActivity(ctx contractapi.TransactionContextInterface, userID, activity, x, y, seed string) error {
    if userID == "" {
        return fmt.Errorf("userID is required")
    }
    px, err := parseCoord(x)
    if err != nil {
        return err
    }
    py, err := parseCoord(y)
    if err != nil {
        return err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if seed != "" && cfg.Seed != seed {
        return fmt.Errorf(
            "seed %q does not match the layout in place (%q) — re-seed before mixing scenarios",
            seed, cfg.Seed)
    }
    trackCapacity := cfg.TrackCapacity

    rep, best, err := s.admit(ctx, userID, px, py)
    if err != nil {
        return err
    }

    // Writing the cell back is what creates the hot key, so it only happens
    // when something on the cell actually changes. See SeedNetwork.
    cellChanged := false
    if trackCapacity {
        best.UsedCapacity++
        cellChanged = true
    }
    if cfg.TrackBandwidth {
        best.AllocatedHz += cfg.RequestHz
        cellChanged = true
    }
    // The operator of the serving cell is credited for the service. This
    // lands on the cell record, which is already a hot key when spectrum
    // is tracked — see SetCapacity for what that costs.
    if cfg.TrackEconomy {
        best.EarnedMicro += transactionCost(cfg)
        cellChanged = true
    }
    if cellChanged {
        if err := s.saveAntenna(ctx, best); err != nil {
            return err
        }
    }

    // The wallet is keyed per entity, so debiting never contends between
    // entities — unlike crediting the operator above.
    if cfg.TrackEconomy {
        acct, aerr := s.accountOf(ctx, userID, cfg)
        if aerr != nil {
            return aerr
        }
        cost := transactionCost(cfg)
        acct.BalanceMicro -= cost
        acct.SpentMicro += cost
        acct.TxCount++
        acct.Timestamp = txTimestamp(ctx)
        ab, aerr := json.Marshal(acct)
        if aerr != nil {
            return aerr
        }
        if aerr := ctx.GetStub().PutState(tokenPrefix+userID, ab); aerr != nil {
            return aerr
        }
    }

    // Record what this entity now holds, so a later sublet can be checked
    // against a figure this contract issued rather than one the caller
    // claims to own.
    if cfg.TrackBandwidth {
        g, gerr := s.grantOf(ctx, userID)
        if gerr != nil {
            return gerr
        }
        g.Cell = rep.ServingCell
        g.HeldHz += cfg.RequestHz
        if gerr := s.saveGrant(ctx, g); gerr != nil {
            return gerr
        }
    }

    // The battery is keyed per entity, so this write never contends.
    if cfg.TrackEnergy {
        budget, berr := s.energyOf(ctx, userID, cfg)
        if berr != nil {
            return berr
        }
        budget.RemainingMicroJ -= rep.EnergyMicroJ
        budget.SpentMicroJ += rep.EnergyMicroJ
        budget.TxCount++
        budget.Timestamp = txTimestamp(ctx)
        bb, berr := json.Marshal(budget)
        if berr != nil {
            return berr
        }
        if berr := ctx.GetStub().PutState(energyPrefix+userID, bb); berr != nil {
            return berr
        }
    }

    record := UserActivity{
        UserID: userID,
        Activity: activity,
        X:            px,
        Y:            py,
        ServingCell:  rep.ServingCell,
        DistanceM:    rep.DistanceM,
        RssiMilliDbm: rep.RssiMilliDbm,
        SinrMilliDb:  rep.SinrMilliDb,
        CapacityBps:  rep.CapacityBps,
        GrantedHz:    rep.GrantedHz,
        TxTimeMicroS: rep.TxTimeMicroS,
        EnergyMicroJ: rep.EnergyMicroJ,
        Timestamp:    txTimestamp(ctx),
    }
    recordJSON, err := json.Marshal(record)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(userID, recordJSON)
}

func (s *LocationBasedUserActivity) QueryAsset(ctx contractapi.TransactionContextInterface, userID string) (*UserActivity, error) {
    assetJSON, err := ctx.GetStub().GetState(userID)
    if err != nil {
        return nil, fmt.Errorf("failed to read from world state: %v", err)
    }
    if assetJSON == nil {
        return nil, fmt.Errorf("record %s does not exist", userID)
    }
    var asset UserActivity
    if err := json.Unmarshal(assetJSON, &asset); err != nil {
        return nil, err
    }
    return &asset, nil
}

// QueryAllAssets skips the model keys, which carry the "~" prefix.
func (s *LocationBasedUserActivity) QueryAllAssets(ctx contractapi.TransactionContextInterface) ([]*UserActivity, error) {
    it, err := ctx.GetStub().GetStateByRange("", "")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var assets []*UserActivity
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        if len(kv.Key) > 0 && kv.Key[0] == '~' {
            continue
        }
        var asset UserActivity
        if err := json.Unmarshal(kv.Value, &asset); err != nil {
            continue
        }
        assets = append(assets, &asset)
    }
    return assets, nil
}

// ValidateCoverage answers whether a recorded entity still meets the SINR
// threshold — the decision a real network makes before a handover.
func (s *LocationBasedUserActivity) ValidateCoverage(ctx contractapi.TransactionContextInterface, userID string) (bool, error) {
    asset, err := s.QueryAsset(ctx, userID)
    if err != nil {
        return false, err
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return false, err
    }
    return asset.SinrMilliDb >= cfg.MinSinrMilliDb, nil
}

// ═══════════════════════════════════════════════════════════════════════
// Network model — antenna registry, cell selection and admission control.
//
// Each chaincode in Fabric owns an isolated state space, so a contract
// cannot see antennas registered by any other chaincode. Every contract
// therefore keeps its own registry, seeded through SeedNetwork.
//
// Key layout: entity records keep their bare id, so QueryAsset is unchanged.
// Model keys carry a "~" prefix, which sorts after alphanumerics and lets
// QueryAllAssets skip them.
// ═══════════════════════════════════════════════════════════════════════

const antennaPrefix = "~ANT:"
const configKey = "~CFG"

// Antenna is one macrocell: where it is, what it radiates, how loaded it is.
type Antenna struct {
    AntennaID       string `json:"antennaID"`
    X               int64  `json:"x"`
    Y               int64  `json:"y"`
    TxPowerMilliDbm int64  `json:"txPowerMilliDbm"`
    GainMilliDb     int64  `json:"gainMilliDb"`
    FreqMHz         int64  `json:"freqMHz"`
    BandwidthHz     int64  `json:"bandwidthHz"`
    MaxCapacity     int64  `json:"maxCapacity"`
    UsedCapacity    int64  `json:"usedCapacity"`
    AllocatedHz     int64  `json:"allocatedHz"`
    LoadFactor      int64  `json:"loadFactorHundredths"`
    EarnedMicro     int64  `json:"earnedMicro"`
}

// NetworkConfig holds the propagation parameters the whole cell layout
// shares. Stored once at seed time so every later transaction evaluates
// against the same environment.
type NetworkConfig struct {
    Seed                  string `json:"seed"`
    GridSizeM             int64  `json:"gridSizeM"`
    AntennaCount          int64  `json:"antennaCount"`
    PathLossExponentMilli int64  `json:"pathLossExponentMilli"`
    ShadowSigmaMilliDb    int64  `json:"shadowSigmaMilliDb"`
    NoiseFigureMilliDb    int64  `json:"noiseFigureMilliDb"`
    MinSinrMilliDb        int64  `json:"minSinrMilliDb"`
    TrackCapacity         bool   `json:"trackCapacity"`

    // Resource accounting, modelled on the uplink cost formulation in
    // Zuo, Jin & Zhang (VTC2021-Fall): a bandwidth share per entity, a
    // rate that follows from that share, and an energy budget spent at
    // e = P·D/R with the constraint e ≤ E_max.
    //
    // Both are off by default. Turning on bandwidth means writing the
    // cell record on every admission, which is a read-modify-write on one
    // of only eight keys — see SetCapacity for what that costs. Energy is
    // keyed per entity, so it carries no such contention.
    TrackBandwidth        bool   `json:"trackBandwidth"`
    RequestHz             int64  `json:"requestHz"`
    TrackEnergy           bool   `json:"trackEnergy"`
    EnergyBudgetMicroJ    int64  `json:"energyBudgetMicroJ"`
    TxPowerMilliDbm       int64  `json:"txPowerMilliDbm"`
    PayloadBits           int64  `json:"payloadBits"`

    // Association policy. "nearest" picks the strongest cell and stops —
    // the traditional NBA rule. "loadaware" implements Algorithm 2 of Zuo,
    // Jin & Zhang: walk the candidates strongest-first and take the first
    // one whose load is still under its share, so a busy cell hands its
    // overflow to the next-best rather than refusing service.
    // Market
    Stripes               int64  `json:"stripes"`
    PriceScale            int64  `json:"priceScale"`
    RelayShareHundred     int64  `json:"relaySharePercent"`
    WorkReward            int64  `json:"workReward"`

    AssociationMode       string `json:"associationMode"`
    LoadToleranceHundred  int64  `json:"loadToleranceHundredths"`

    // Charging, following the cost/revenue structure of the same paper:
    // users pay for the spectrum they hold and the data they move, and the
    // operator of the serving cell is credited.
    TrackEconomy          bool   `json:"trackEconomy"`
    PricePerKHzMicro      int64  `json:"pricePerKHzMicro"`
    PricePerKbitMicro     int64  `json:"pricePerKbitMicro"`
    InitialBalanceMicro   int64  `json:"initialBalanceMicro"`
}

// TokenAccount is one entity's wallet. Like the energy budget it lives
// under its own key, so spending never contends between entities.
type TokenAccount struct {
    EntityID     string `json:"entityID"`
    BalanceMicro int64  `json:"balanceMicro"`
    SpentMicro   int64  `json:"spentMicro"`
    TxCount      int64  `json:"txCount"`
    Timestamp    string `json:"timestamp"`
}

// EnergyBudget is one entity's battery. It lives under its own key, so
// two entities never contend — the asymmetry with the shared bandwidth
// pool is the point worth measuring.
type EnergyBudget struct {
    EntityID        string `json:"entityID"`
    TotalMicroJ     int64  `json:"totalMicroJ"`
    RemainingMicroJ int64  `json:"remainingMicroJ"`
    SpentMicroJ     int64  `json:"spentMicroJ"`
    TxCount         int64  `json:"txCount"`
    Timestamp       string `json:"timestamp"`
}

// CellReport is what the radio evaluation produces for one position.
type CellReport struct {
    ServingCell   string `json:"servingCell"`
    DistanceM     int64  `json:"distanceM"`
    RssiMilliDbm  int64  `json:"rssiMilliDbm"`
    SinrMilliDb   int64  `json:"sinrMilliDb"`
    CapacityBps   int64  `json:"capacityBps"`
    PathLossMilli int64  `json:"pathLossMilliDb"`
    ShadowMilliDb int64  `json:"shadowMilliDb"`
    Candidates    int64  `json:"candidates"`
    UsedCapacity  int64  `json:"usedCapacity"`
    MaxCapacity   int64  `json:"maxCapacity"`
    GrantedHz     int64  `json:"grantedHz"`
    FreeHz        int64  `json:"freeHz"`
    TxTimeMicroS  int64  `json:"txTimeMicroS"`
    EnergyMicroJ  int64  `json:"energyMicroJ"`
    Rank          int64  `json:"rank"`
}

// CellLoad is one cell's spectrum load against the share it should carry.
type CellLoad struct {
    AntennaID    string `json:"antennaID"`
    AllocatedHz  int64  `json:"allocatedHz"`
    BandwidthHz  int64  `json:"bandwidthHz"`
    FairShareHz  int64  `json:"fairShareHz"`
    DeviationHz  int64  `json:"deviationHz"`
    UsedCapacity int64  `json:"usedCapacity"`
    EarnedMicro  int64  `json:"earnedMicro"`
}

// Defaults model a 3.5 GHz macrocell deployment.
const (
    defaultTxPowerMilliDbm = int64(46000)  // 46 dBm
    defaultGainMilliDb     = int64(15000)  // 15 dBi
    defaultFreqMHz         = int64(3500)   // 3.5 GHz
    defaultBandwidthHz     = int64(20000000)
    defaultMaxCapacity     = int64(0)      // 0 = unlimited, capacity not tracked
    defaultGridSizeM       = int64(10000)  // 10 km square
    defaultAntennaCount    = int64(8)      // one per organization
    defaultExponentMilli   = int64(300)    // n = 3.0, urban
    defaultShadowSigma     = int64(8000)   // 8 dB
    defaultNoiseFigure     = int64(7000)   // 7 dB
    defaultMinSinr         = int64(-6000)  // −6 dB decoding floor
    defaultRequestHz       = int64(100000) // 100 kHz per entity
    defaultEnergyMicroJ    = int64(5000000) // 5 J, the budget used in the paper
    defaultTxPowerMilliDbm = int64(23000)  // 23 dBm entity uplink
    defaultPayloadBits     = int64(3808)   // 608-bit header + 100 × 32-bit
    defaultLoadFactor      = int64(100)    // ε = 1.0; a macro tier would be higher
    defaultLoadTolerance   = int64(120)    // admit up to 1.2× the fair share
    defaultPricePerKHz     = int64(10)     // micro-coin per kHz held
    defaultPricePerKbit    = int64(100)    // micro-coin per kbit moved
    defaultInitialBalance  = int64(1000000000) // 1000 coins
    energyPrefix           = "~NRG:"
    tokenPrefix            = "~TOK:"
)

// SeedNetwork lays out the antenna grid. Placement is pseudo-random but
// derived entirely from the seed, so the same seed reproduces the same
// network on every peer and in every replay — which is what makes a
// benchmark comparable across runs.
//
// maxCapacity is how many entities one cell will admit. Zero — the default —
// means unlimited AND turns off capacity accounting entirely.
//
// That second half matters more than it looks. Counting admissions means
// incrementing a field on the serving cell's record, which is a
// read-modify-write on one of only eight keys. Fabric validates read sets
// after ordering: when several transactions in the same block read the same
// key at the same version, one commits and the rest are rejected with
// MVCC_READ_CONFLICT. At 20 tps the busiest cell takes about eight
// transactions per block, so roughly 20% would survive; at 109 tps, under 4%.
// A throughput benchmark would be measuring lock contention on eight keys
// rather than anything about the network.
//
// So capacity tracking is opt-in. Turn it on when admission control is the
// subject of the experiment — the contention is then the finding, not an
// artefact — and leave it off when measuring throughput.
//
// Passing "" for a numeric argument accepts the default.
func (s *LocationBasedUserActivity) SeedNetwork(ctx contractapi.TransactionContextInterface, seed, antennaCount, gridSizeM, maxCapacity string) error {
    if seed == "" {
        return fmt.Errorf("a seed is required so the layout can be reproduced")
    }
    count := parseIntOr(antennaCount, defaultAntennaCount)
    grid := parseIntOr(gridSizeM, defaultGridSizeM)
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    if count < 1 || count > 256 {
        return fmt.Errorf("antennaCount must be between 1 and 256, got %d", count)
    }
    if grid < 100 {
        return fmt.Errorf("gridSizeM must be at least 100, got %d", grid)
    }

    for i := int64(0); i < count; i++ {
        id := fmt.Sprintf("antenna-%d", i+1)
        x, y := PlaceOnGrid(seed, id, grid)
        a := Antenna{
            AntennaID:       id,
            X:               x,
            Y:               y,
            TxPowerMilliDbm: defaultTxPowerMilliDbm,
            GainMilliDb:     defaultGainMilliDb,
            FreqMHz:         defaultFreqMHz,
            BandwidthHz:     defaultBandwidthHz,
            MaxCapacity:     capacity,
            UsedCapacity:    0,
            AllocatedHz:     0,
            LoadFactor:      defaultLoadFactor,
            EarnedMicro:     0,
        }
        if err := s.saveAntenna(ctx, &a); err != nil {
            return err
        }
    }

    cfg := NetworkConfig{
        Seed:                  seed,
        GridSizeM:             grid,
        AntennaCount:          count,
        PathLossExponentMilli: defaultExponentMilli,
        ShadowSigmaMilliDb:    defaultShadowSigma,
        NoiseFigureMilliDb:    defaultNoiseFigure,
        MinSinrMilliDb:        defaultMinSinr,
        TrackCapacity:         capacity > 0,
        TrackBandwidth:        false,
        RequestHz:             defaultRequestHz,
        TrackEnergy:           false,
        EnergyBudgetMicroJ:    defaultEnergyMicroJ,
        TxPowerMilliDbm:       defaultTxPowerMilliDbm,
        PayloadBits:           defaultPayloadBits,
        Stripes:               defaultStripes,
        PriceScale:            defaultPriceScale,
        RelayShareHundred:     50,
        WorkReward:            defaultWorkReward,
        AssociationMode:       "nearest",
        LoadToleranceHundred:  defaultLoadTolerance,
        TrackEconomy:          false,
        PricePerKHzMicro:      defaultPricePerKHz,
        PricePerKbitMicro:     defaultPricePerKbit,
        InitialBalanceMicro:   defaultInitialBalance,
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetPropagation overrides the environment without moving the antennas, so
// a sweep can vary one parameter at a time.
func (s *LocationBasedUserActivity) SetPropagation(ctx contractapi.TransactionContextInterface, exponentMilli, shadowSigmaMilliDb, minSinrMilliDb string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.PathLossExponentMilli = parseIntOr(exponentMilli, cfg.PathLossExponentMilli)
    cfg.ShadowSigmaMilliDb = parseIntOr(shadowSigmaMilliDb, cfg.ShadowSigmaMilliDb)
    cfg.MinSinrMilliDb = parseIntOr(minSinrMilliDb, cfg.MinSinrMilliDb)
    if cfg.PathLossExponentMilli < 150 || cfg.PathLossExponentMilli > 600 {
        return fmt.Errorf("path-loss exponent must be between 1.5 and 6.0")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetCapacity re-caps every cell without moving them, so an admission-control
// sweep can vary the limit while holding the layout fixed.
func (s *LocationBasedUserActivity) SetCapacity(ctx contractapi.TransactionContextInterface, maxCapacity string) error {
    capacity := parseIntOr(maxCapacity, defaultMaxCapacity)
    if capacity < 0 {
        return fmt.Errorf("maxCapacity cannot be negative, got %d", capacity)
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    for _, a := range antennas {
        a.MaxCapacity = capacity
        if err := s.saveAntenna(ctx, a); err != nil {
            return err
        }
    }
    return nil
}

// SetResources turns the two accounting mechanisms on or off and sets
// their parameters. Both default to off so a throughput benchmark is not
// silently measuring something else.
//
//   requestHz     spectrum each entity is granted; 0 keeps the current value
//   energyMicroJ  starting battery per entity
//   txPowerMdbm   entity uplink power, used for e = P·D/R
//   payloadBits   how much each transaction transmits
//
// Pass "off" for trackBandwidth or trackEnergy to disable, "on" to enable.
func (s *LocationBasedUserActivity) SetResources(ctx contractapi.TransactionContextInterface, trackBandwidth, trackEnergy, requestHz, energyMicroJ, txPowerMdbm, payloadBits string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if trackBandwidth != "" {
        cfg.TrackBandwidth = trackBandwidth == "on" || trackBandwidth == "true"
    }
    if trackEnergy != "" {
        cfg.TrackEnergy = trackEnergy == "on" || trackEnergy == "true"
    }
    cfg.RequestHz = parseIntOr(requestHz, cfg.RequestHz)
    cfg.EnergyBudgetMicroJ = parseIntOr(energyMicroJ, cfg.EnergyBudgetMicroJ)
    cfg.TxPowerMilliDbm = parseIntOr(txPowerMdbm, cfg.TxPowerMilliDbm)
    cfg.PayloadBits = parseIntOr(payloadBits, cfg.PayloadBits)

    if cfg.RequestHz < 1 {
        return fmt.Errorf("requestHz must be positive, got %d", cfg.RequestHz)
    }
    if cfg.PayloadBits < 1 {
        return fmt.Errorf("payloadBits must be positive, got %d", cfg.PayloadBits)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetAssociation switches between the traditional nearest-cell rule and
// the load-aware alternative, and sets how far above its share a cell may
// go before it starts handing entities on.
//
//   mode       "nearest" or "loadaware"
//   tolerance  hundredths; 120 means 1.2× the fair share
func (s *LocationBasedUserActivity) SetAssociation(ctx contractapi.TransactionContextInterface, mode, toleranceHundredths string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if mode != "" {
        if mode != "nearest" && mode != "loadaware" {
            return fmt.Errorf("mode must be nearest or loadaware, got %q", mode)
        }
        cfg.AssociationMode = mode
    }
    cfg.LoadToleranceHundred = parseIntOr(toleranceHundredths, cfg.LoadToleranceHundred)
    if cfg.LoadToleranceHundred < 100 {
        return fmt.Errorf("tolerance below 100 would refuse every cell")
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// SetTier sets one cell's load factor — ε_m in the paper. A macro cell
// carrying twice its neighbours' load is SetTier("antenna-1", "200").
func (s *LocationBasedUserActivity) SetTier(ctx contractapi.TransactionContextInterface, antennaID, loadFactorHundredths string) error {
    b, err := ctx.GetStub().GetState(antennaPrefix + antennaID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("antenna %s is not registered", antennaID)
    }
    var a Antenna
    if err := json.Unmarshal(b, &a); err != nil {
        return err
    }
    a.LoadFactor = parseIntOr(loadFactorHundredths, a.LoadFactor)
    if a.LoadFactor < 1 {
        return fmt.Errorf("load factor must be positive")
    }
    return s.saveAntenna(ctx, &a)
}

// SetEconomy turns charging on or off and sets the tariff.
func (s *LocationBasedUserActivity) SetEconomy(ctx contractapi.TransactionContextInterface, track, pricePerKHz, pricePerKbit, initialBalance string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if track != "" {
        cfg.TrackEconomy = track == "on" || track == "true"
    }
    cfg.PricePerKHzMicro = parseIntOr(pricePerKHz, cfg.PricePerKHzMicro)
    cfg.PricePerKbitMicro = parseIntOr(pricePerKbit, cfg.PricePerKbitMicro)
    cfg.InitialBalanceMicro = parseIntOr(initialBalance, cfg.InitialBalanceMicro)
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

// energyOf reads an entity's battery, creating it at full charge on first
// use so a benchmark does not need a separate provisioning pass.
func (s *LocationBasedUserActivity) energyOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*EnergyBudget, error) {
    b, err := ctx.GetStub().GetState(energyPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &EnergyBudget{
            EntityID:        entityID,
            TotalMicroJ:     cfg.EnergyBudgetMicroJ,
            RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        }, nil
    }
    var e EnergyBudget
    if err := json.Unmarshal(b, &e); err != nil {
        return nil, err
    }
    return &e, nil
}

// EnergyOf reports an entity's remaining battery.
func (s *LocationBasedUserActivity) EnergyOf(ctx contractapi.TransactionContextInterface, entityID string) (*EnergyBudget, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.energyOf(ctx, entityID, cfg)
}

// RechargeEntity restores a battery to full — the counterpart to depletion.
func (s *LocationBasedUserActivity) RechargeEntity(ctx contractapi.TransactionContextInterface, entityID string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    e := EnergyBudget{
        EntityID:        entityID,
        TotalMicroJ:     cfg.EnergyBudgetMicroJ,
        RemainingMicroJ: cfg.EnergyBudgetMicroJ,
        Timestamp:       txTimestamp(ctx),
    }
    b, err := json.Marshal(e)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, b)
}

// SpectrumStatus reports how much of each cell's spectrum is committed.
func (s *LocationBasedUserActivity) SpectrumStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}

// transactionCost prices one service grant, following the cost structure
// of the paper: a charge for the spectrum held and a charge for the data
// moved. Deterministic and integer, like everything else here.
func transactionCost(cfg *NetworkConfig) int64 {
    spectrum := (cfg.RequestHz / 1000) * cfg.PricePerKHzMicro
    data := (cfg.PayloadBits / 1000) * cfg.PricePerKbitMicro
    return spectrum + data
}

func (s *LocationBasedUserActivity) accountOf(ctx contractapi.TransactionContextInterface, entityID string, cfg *NetworkConfig) (*TokenAccount, error) {
    b, err := ctx.GetStub().GetState(tokenPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &TokenAccount{EntityID: entityID, BalanceMicro: cfg.InitialBalanceMicro}, nil
    }
    var a TokenAccount
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

// BalanceOf reports an entity's wallet.
func (s *LocationBasedUserActivity) BalanceOf(ctx contractapi.TransactionContextInterface, entityID string) (*TokenAccount, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    return s.accountOf(ctx, entityID, cfg)
}

// Credit tops up a wallet.
func (s *LocationBasedUserActivity) Credit(ctx contractapi.TransactionContextInterface, entityID, amountMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    acct, err := s.accountOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    acct.BalanceMicro += amount
    acct.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(acct)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+entityID, b)
}

// Transfer moves value between two wallets.
//
// Both keys are per-entity, so two transfers between different pairs never
// contend. Two transfers from the SAME payer in one block do — that is the
// account-model limit in Fabric, and it is inherent rather than a defect
// of this code.
func (s *LocationBasedUserActivity) Transfer(ctx contractapi.TransactionContextInterface, fromID, toID, amountMicro string) error {
    if fromID == toID {
        return fmt.Errorf("cannot transfer to the same account")
    }
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    amount := parseIntOr(amountMicro, 0)
    if amount <= 0 {
        return fmt.Errorf("amount must be positive, got %d", amount)
    }
    from, err := s.accountOf(ctx, fromID, cfg)
    if err != nil {
        return err
    }
    if from.BalanceMicro < amount {
        return fmt.Errorf("%s has %d micro-coin, cannot send %d",
            fromID, from.BalanceMicro, amount)
    }
    to, err := s.accountOf(ctx, toID, cfg)
    if err != nil {
        return err
    }
    from.BalanceMicro -= amount
    from.SpentMicro += amount
    from.Timestamp = txTimestamp(ctx)
    to.BalanceMicro += amount
    to.Timestamp = txTimestamp(ctx)

    fb, err := json.Marshal(from)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(tokenPrefix+fromID, fb); err != nil {
        return err
    }
    tb, err := json.Marshal(to)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(tokenPrefix+toID, tb)
}

// Quote prices a service grant without charging for it.
func (s *LocationBasedUserActivity) Quote(ctx contractapi.TransactionContextInterface) (int64, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return 0, err
    }
    return transactionCost(cfg), nil
}

func (s *LocationBasedUserActivity) saveAntenna(ctx contractapi.TransactionContextInterface, a *Antenna) error {
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(antennaPrefix+a.AntennaID, b)
}

func (s *LocationBasedUserActivity) loadConfig(ctx contractapi.TransactionContextInterface) (*NetworkConfig, error) {
    b, err := ctx.GetStub().GetState(configKey)
    if err != nil {
        return nil, fmt.Errorf("failed to read the network config: %v", err)
    }
    if b == nil {
        return nil, fmt.Errorf("no antenna layout yet — call SeedNetwork first")
    }
    var cfg NetworkConfig
    if err := json.Unmarshal(b, &cfg); err != nil {
        return nil, err
    }
    return &cfg, nil
}

func (s *LocationBasedUserActivity) listAntennas(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    it, err := ctx.GetStub().GetStateByRange(antennaPrefix, antennaPrefix+"\uffff")
    if err != nil {
        return nil, err
    }
    defer it.Close()

    var out []*Antenna
    for it.HasNext() {
        kv, err := it.Next()
        if err != nil {
            return nil, err
        }
        var a Antenna
        if err := json.Unmarshal(kv.Value, &a); err != nil {
            continue
        }
        out = append(out, &a)
    }
    if len(out) == 0 {
        return nil, fmt.Errorf("no antennas registered — call SeedNetwork first")
    }
    return out, nil
}

// evaluate ranks every cell for a position.
//
// Received power is computed for each antenna through path loss and a
// per-link shadow fade. The candidates come back ordered strongest-first;
// for each one, SINR treats that cell as the server and all others as
// interference, so the figures are correct whichever candidate is finally
// chosen. That is what makes Algorithm 2 possible: falling back to the
// second-best cell needs the second-best cell's SINR, not the first's.
func (s *LocationBasedUserActivity) evaluate(antennas []*Antenna, cfg *NetworkConfig, entityID string, x, y int64) ([]*CellReport, []*Antenna, error) {
    n := len(antennas)
    if n == 0 {
        return nil, nil, fmt.Errorf("no antennas registered")
    }

    rssi := make([]int64, n)
    dist := make([]int64, n)
    pl := make([]int64, n)
    shadow := make([]int64, n)

    for i, a := range antennas {
        dist[i] = DistanceM(x, y, a.X, a.Y)
        pl[i] = PathLossMilliDb(dist[i], a.FreqMHz, cfg.PathLossExponentMilli)
        shadow[i] = ShadowingMilliDb(cfg.Seed, entityID, a.AntennaID, cfg.ShadowSigmaMilliDb)
        rssi[i] = RssiMilliDbm(a.TxPowerMilliDbm, a.GainMilliDb, pl[i], shadow[i])
    }

    // Order by received power, strongest first. Insertion sort: eight cells
    // makes anything cleverer pointless, and this stays deterministic.
    order := make([]int, n)
    for i := range order {
        order[i] = i
    }
    for i := 1; i < n; i++ {
        k := order[i]
        j := i - 1
        for j >= 0 && rssi[order[j]] < rssi[k] {
            order[j+1] = order[j]
            j--
        }
        order[j+1] = k
    }

    reports := make([]*CellReport, n)
    cells := make([]*Antenna, n)

    for rank, idx := range order {
        a := antennas[idx]
        interferers := make([]int64, 0, n-1)
        for j := range antennas {
            if j != idx {
                interferers = append(interferers, rssi[j])
            }
        }
        noise := NoiseFloorMilliDbm(a.BandwidthHz, cfg.NoiseFigureMilliDb)
        sinr := SinrMilliDb(rssi[idx], interferers, noise)

        // With spectrum accounting on, the achievable rate follows from the
        // slice this entity is granted rather than the whole cell. That is
        // the difference between "this link could carry 77 Mbps" and "this
        // entity can carry 0.39 Mbps".
        rateBandwidth := a.BandwidthHz
        granted := int64(0)
        free := a.BandwidthHz
        if cfg.TrackBandwidth {
            granted = cfg.RequestHz
            free = a.BandwidthHz - a.AllocatedHz
            rateBandwidth = cfg.RequestHz
        }
        capacity := ShannonBps(rateBandwidth, sinr)

        reports[rank] = &CellReport{
            ServingCell:   a.AntennaID,
            DistanceM:     dist[idx],
            RssiMilliDbm:  rssi[idx],
            SinrMilliDb:   sinr,
            CapacityBps:   capacity,
            PathLossMilli: pl[idx],
            ShadowMilliDb: shadow[idx],
            Candidates:    int64(n),
            UsedCapacity:  a.UsedCapacity,
            MaxCapacity:   a.MaxCapacity,
            GrantedHz:     granted,
            FreeHz:        free,
            TxTimeMicroS:  TransmitTimeMicroS(cfg.PayloadBits, capacity),
            EnergyMicroJ:  TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, capacity),
            Rank:          int64(rank + 1),
        }
        cells[rank] = a
    }
    return reports, cells, nil
}

// fairShareHz is the load each cell would carry if spectrum were spread
// evenly, scaled by that cell's tier factor — X̄ and ε_m in the paper.
func fairShareHz(antennas []*Antenna) int64 {
    total := int64(0)
    for _, a := range antennas {
        total += a.AllocatedHz
    }
    return total / int64(len(antennas))
}

// loadDeviation is |Σ X_j − ε_m·X̄|, the balance metric the paper reports.
func loadDeviation(a *Antenna, share int64) int64 {
    target := (share * a.LoadFactor) / 100
    d := a.AllocatedHz - target
    if d < 0 {
        return -d
    }
    return d
}

// LoadBalance reports each cell's spectrum load against its fair share.
// Lower deviation means better balance — the comparison the paper draws
// between nearest-cell association and its load-aware alternative.
func (s *LocationBasedUserActivity) LoadBalance(ctx contractapi.TransactionContextInterface) ([]*CellLoad, error) {
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    share := fairShareHz(antennas)
    out := make([]*CellLoad, 0, len(antennas))
    for _, a := range antennas {
        out = append(out, &CellLoad{
            AntennaID:   a.AntennaID,
            AllocatedHz: a.AllocatedHz,
            BandwidthHz: a.BandwidthHz,
            FairShareHz: (share * a.LoadFactor) / 100,
            DeviationHz: loadDeviation(a, share),
            UsedCapacity: a.UsedCapacity,
            EarnedMicro: a.EarnedMicro,
        })
    }
    return out, nil
}

// admit chooses a cell and applies every constraint that can refuse one.
//
// Under "nearest" only the strongest candidate is considered, and a full
// cell means refusal. Under "loadaware" the candidates are walked in order
// and the first one that clears every check wins — so an overloaded cell
// sheds to its neighbour instead of dropping the entity.
func (s *LocationBasedUserActivity) admit(ctx contractapi.TransactionContextInterface, entityID string, x, y int64) (*CellReport, *Antenna, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, nil, err
    }
    reports, cells, err := s.evaluate(antennas, cfg, entityID, x, y)
    if err != nil {
        return nil, nil, err
    }

    loadAware := cfg.AssociationMode == "loadaware" && cfg.TrackBandwidth
    share := fairShareHz(antennas)

    // The paper computes X̄ from the whole user population up front. A
    // ledger sees entities one at a time, so the running average stands in
    // for it — but early on that average is near zero and the rule would
    // refuse every cell. It only starts biting once there is load to
    // balance, which is one grant per cell.
    applyLoadRule := loadAware && share >= cfg.RequestHz

    var firstRep *CellReport
    var firstCell *Antenna
    var lastErr error

    // Two passes. The first honours the load rule; if no cell is under its
    // share, the second drops that rule and takes the best cell that has
    // room. Refusing service because every cell is busy would be worse than
    // an unbalanced assignment.
    for pass := 0; pass < 2; pass++ {
        useLoadRule := applyLoadRule && pass == 0
        if pass == 1 && !applyLoadRule {
            break // the first pass already had no load rule
        }
        limit := 1
        if loadAware {
            limit = len(reports)
        }

        for i := 0; i < limit; i++ {
            rep, cell := reports[i], cells[i]
            if firstRep == nil {
                firstRep, firstCell = rep, cell
            }

            if rep.SinrMilliDb < cfg.MinSinrMilliDb {
                lastErr = fmt.Errorf(
                    "out of coverage: SINR %d mdB on %s is below the %d mdB threshold",
                    rep.SinrMilliDb, rep.ServingCell, cfg.MinSinrMilliDb)
                continue
            }
            if cfg.TrackCapacity && cell.UsedCapacity >= cell.MaxCapacity {
                lastErr = fmt.Errorf("cell %s is saturated: %d of %d in use",
                    cell.AntennaID, cell.UsedCapacity, cell.MaxCapacity)
                continue
            }
            if cfg.TrackBandwidth && cell.AllocatedHz+cfg.RequestHz > cell.BandwidthHz {
                lastErr = fmt.Errorf("cell %s has no spectrum left: %d Hz free, %d Hz requested",
                    cell.AntennaID, cell.BandwidthHz-cell.AllocatedHz, cfg.RequestHz)
                continue
            }
            if useLoadRule {
                tolerated := (share * cell.LoadFactor * cfg.LoadToleranceHundred) / 10000
                if cell.AllocatedHz+cfg.RequestHz > tolerated {
                    lastErr = fmt.Errorf("cell %s is above its share: %d Hz against %d Hz tolerated",
                        cell.AntennaID, cell.AllocatedHz, tolerated)
                    continue
                }
            }

            if cfg.TrackEnergy {
                if rep.EnergyMicroJ < 0 {
                    lastErr = fmt.Errorf("link to %s carries no usable rate", cell.AntennaID)
                    continue
                }
                budget, berr := s.energyOf(ctx, entityID, cfg)
                if berr != nil {
                    return rep, cell, berr
                }
                if budget.RemainingMicroJ < rep.EnergyMicroJ {
                    // A flat battery is the entity's problem, not the cell's,
                    // so another cell cannot help — a weaker one costs more.
                    return rep, cell, fmt.Errorf(
                        "%s has %d µJ left but the transmission costs %d µJ",
                        entityID, budget.RemainingMicroJ, rep.EnergyMicroJ)
                }
            }

            if cfg.TrackEconomy {
                cost := transactionCost(cfg)
                acct, aerr := s.accountOf(ctx, entityID, cfg)
                if aerr != nil {
                    return rep, cell, aerr
                }
                if acct.BalanceMicro < cost {
                    return rep, cell, fmt.Errorf(
                        "%s has %d micro-coin but the service costs %d",
                        entityID, acct.BalanceMicro, cost)
                }
            }

            return rep, cell, nil
        }
    }

    if lastErr == nil {
        lastErr = fmt.Errorf("no cell could serve this position")
    }
    return firstRep, firstCell, lastErr
}

// ServingCell reports which cell would serve a position, without writing.
// A planning query rather than a connection request.
func (s *LocationBasedUserActivity) ServingCell(ctx contractapi.TransactionContextInterface, entityID, x, y string) (*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    if err != nil {
        return nil, err
    }
    return reports[0], nil
}

// RankCells returns every candidate for a position, strongest first — what
// load-aware association walks through when the best cell is busy.
func (s *LocationBasedUserActivity) RankCells(ctx contractapi.TransactionContextInterface, entityID, x, y string) ([]*CellReport, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return nil, err
    }
    px, err := parseCoord(x)
    if err != nil {
        return nil, err
    }
    py, err := parseCoord(y)
    if err != nil {
        return nil, err
    }
    reports, _, err := s.evaluate(antennas, cfg, entityID, px, py)
    return reports, err
}

// NetworkStatus returns the current load of every cell.
func (s *LocationBasedUserActivity) NetworkStatus(ctx contractapi.TransactionContextInterface) ([]*Antenna, error) {
    return s.listAntennas(ctx)
}


// Release gives back one unit of capacity — the counterpart to admission,
// so a long benchmark does not saturate every cell and stall.
func (s *LocationBasedUserActivity) Release(ctx contractapi.TransactionContextInterface, entityID string) error {
    b, err := ctx.GetStub().GetState(entityID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("%s holds no allocation", entityID)
    }
    var rec UserActivity
    if err := json.Unmarshal(b, &rec); err != nil {
        return err
    }
    if rec.ServingCell == "" {
        return fmt.Errorf("%s has no serving cell recorded", entityID)
    }
    ab, err := ctx.GetStub().GetState(antennaPrefix + rec.ServingCell)
    if err != nil {
        return err
    }
    if ab == nil {
        return fmt.Errorf("serving cell %s is not registered", rec.ServingCell)
    }
    var a Antenna
    if err := json.Unmarshal(ab, &a); err != nil {
        return err
    }
    cfg, cerr := s.loadConfig(ctx)
    if cerr != nil {
        return cerr
    }
    if a.UsedCapacity > 0 {
        a.UsedCapacity--
    }
    if cfg.TrackBandwidth {
        a.AllocatedHz -= cfg.RequestHz
        if a.AllocatedHz < 0 {
            a.AllocatedHz = 0
        }
    }
    if err := s.saveAntenna(ctx, &a); err != nil {
        return err
    }
    return ctx.GetStub().DelState(entityID)
}

// ── helpers ─────────────────────────────────────────────────────────

func parseCoord(v string) (int64, error) {
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return 0, fmt.Errorf("coordinate %q must be a whole number of metres", v)
    }
    return n, nil
}

func parseIntOr(v string, fallback int64) int64 {
    if v == "" {
        return fallback
    }
    n, err := strconv.ParseInt(v, 10, 64)
    if err != nil {
        return fallback
    }
    return n
}

func txTimestamp(ctx contractapi.TransactionContextInterface) string {
    ts, err := ctx.GetStub().GetTxTimestamp()
    if err != nil {
        return ""
    }
    return time.Unix(ts.Seconds, int64(ts.Nanos)).UTC().Format(time.RFC3339Nano)
}


// ═══════════════════════════════════════════════════════════════════════
// Resource market — accounts, verifiable sharing, proof of work, relaying.
// ═══════════════════════════════════════════════════════════════════════

const (
    accountPrefix = "~ACC:"
    taskPrefix    = "~TASK:"
    grantPrefix   = "~GRANT:"
    defaultStripes     = int64(1)
    defaultPriceScale  = int64(1000)  // micro-tokens per µJ-equivalent
    defaultWorkReward  = int64(1000)
    maxDifficultyBits  = int64(24)
)

// Account is one participant's balance. It is stored across Stripes
// sub-keys: see stripeOf for why.
type Account struct {
    AccountID   string `json:"accountID"`
    Balance     int64  `json:"balance"`
    Earned      int64  `json:"earned"`
    Spent       int64  `json:"spent"`
    TxCount     int64  `json:"txCount"`
    Timestamp   string `json:"timestamp"`
}

// SpectrumGrant is what an entity holds and may sublet. The contract
// issued it, so the figure cannot be forged by the holder.
type SpectrumGrant struct {
    EntityID  string `json:"entityID"`
    Cell      string `json:"servingCell"`
    HeldHz    int64  `json:"heldHz"`
    SubletHz  int64  `json:"subletHz"`
    Timestamp string `json:"timestamp"`
}

// WorkTask is a unit of computation someone wants done. The reward is
// escrowed at post time, so a worker who solves it is certain to be paid.
type WorkTask struct {
    TaskID          string `json:"taskID"`
    Requester       string `json:"requester"`
    Challenge       string `json:"challenge"`
    DifficultyBits  int64  `json:"difficultyBits"`
    RewardMicro     int64  `json:"rewardMicro"`
    Worker          string `json:"worker"`
    Nonce           string `json:"nonce"`
    Solved          bool   `json:"solved"`
    PostedAt        string `json:"postedAt"`
    SolvedAt        string `json:"solvedAt"`
}

// RelayDeal records a two-hop delivery: the edge entity paid, the relay
// carried. Both figures come from the propagation model, not from either
// party.
type RelayDeal struct {
    DealID        string `json:"dealID"`
    EdgeEntity    string `json:"edgeEntity"`
    RelayEntity   string `json:"relayEntity"`
    DirectEnergy  int64  `json:"directEnergyMicroJ"`
    RelayedEnergy int64  `json:"relayedEnergyMicroJ"`
    SavedMicroJ   int64  `json:"savedMicroJ"`
    PaidMicro     int64  `json:"paidMicro"`
    Timestamp     string `json:"timestamp"`
}

/* ── striping ──────────────────────────────────────────────────────────
   Credits land on a stripe chosen from the transaction id, which every
   endorsing peer derives identically. Debits walk the stripes from the
   same starting point and take from the first that can cover the amount.  */

func stripeOf(ctx contractapi.TransactionContextInterface, accountID string, stripes int64) int64 {
    if stripes <= 1 {
        return 0
    }
    return int64(mix32(fnv1a(ctx.GetStub().GetTxID()+"|"+accountID))) % stripes
}

func stripeKey(accountID string, stripe int64) string {
    return accountPrefix + accountID + ":" + strconv.FormatInt(stripe, 10)
}

func (s *LocationBasedUserActivity) readStripe(ctx contractapi.TransactionContextInterface, accountID string, stripe int64) (*Account, error) {
    b, err := ctx.GetStub().GetState(stripeKey(accountID, stripe))
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &Account{AccountID: accountID}, nil
    }
    var a Account
    if err := json.Unmarshal(b, &a); err != nil {
        return nil, err
    }
    return &a, nil
}

func (s *LocationBasedUserActivity) writeStripe(ctx contractapi.TransactionContextInterface, a *Account, stripe int64) error {
    a.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(a)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(stripeKey(a.AccountID, stripe), b)
}

// credit adds to one stripe — the write that striping is meant to spread.
func (s *LocationBasedUserActivity) credit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    st := stripeOf(ctx, accountID, cfg.Stripes)
    a, err := s.readStripe(ctx, accountID, st)
    if err != nil {
        return err
    }
    a.Balance += amount
    a.Earned += amount
    a.TxCount++
    return s.writeStripe(ctx, a, st)
}

// debit takes from the first stripe that can cover the amount, starting at
// the transaction's own stripe so concurrent debits do not all begin at
// stripe zero.
func (s *LocationBasedUserActivity) debit(ctx contractapi.TransactionContextInterface, accountID string, amount int64, cfg *NetworkConfig) error {
    if amount <= 0 {
        return nil
    }
    start := stripeOf(ctx, accountID, cfg.Stripes)
    for i := int64(0); i < cfg.Stripes; i++ {
        st := (start + i) % cfg.Stripes
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return err
        }
        if a.Balance >= amount {
            a.Balance -= amount
            a.Spent += amount
            a.TxCount++
            return s.writeStripe(ctx, a, st)
        }
    }
    return fmt.Errorf("%s cannot cover %d micro-tokens across %d stripes",
        accountID, amount, cfg.Stripes)
}

// Mint creates tokens. Bootstrap only — there is no supply counter, which
// deliberately avoids one global key every mint would contend on.
func (s *LocationBasedUserActivity) Mint(ctx contractapi.TransactionContextInterface, accountID, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    return s.credit(ctx, accountID, n, cfg)
}

// BalanceOf sums every stripe.
func (s *LocationBasedUserActivity) BalanceOf(ctx contractapi.TransactionContextInterface, accountID string) (*Account, error) {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return nil, err
    }
    total := Account{AccountID: accountID}
    for st := int64(0); st < cfg.Stripes; st++ {
        a, err := s.readStripe(ctx, accountID, st)
        if err != nil {
            return nil, err
        }
        total.Balance += a.Balance
        total.Earned += a.Earned
        total.Spent += a.Spent
        total.TxCount += a.TxCount
    }
    return &total, nil
}

// Transfer moves tokens between accounts. Both keys are per-account, so
// entity-to-entity trade carries no shared-key contention — unlike paying
// an operator, where every payer writes the same few keys.
func (s *LocationBasedUserActivity) Transfer(ctx contractapi.TransactionContextInterface, from, to, amount string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot transfer to the same account")
    }
    n, err := strconv.ParseInt(amount, 10, 64)
    if err != nil || n <= 0 {
        return fmt.Errorf("amount must be a positive whole number, got %q", amount)
    }
    if err := s.debit(ctx, from, n, cfg); err != nil {
        return err
    }
    return s.credit(ctx, to, n, cfg)
}

/* ── sharing what you actually hold ───────────────────────────────────── */

func (s *LocationBasedUserActivity) grantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    b, err := ctx.GetStub().GetState(grantPrefix + entityID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return &SpectrumGrant{EntityID: entityID}, nil
    }
    var g SpectrumGrant
    if err := json.Unmarshal(b, &g); err != nil {
        return nil, err
    }
    return &g, nil
}

func (s *LocationBasedUserActivity) saveGrant(ctx contractapi.TransactionContextInterface, g *SpectrumGrant) error {
    g.Timestamp = txTimestamp(ctx)
    b, err := json.Marshal(g)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(grantPrefix+g.EntityID, b)
}

// GrantOf reports the spectrum an entity holds and how much it has sublet.
func (s *LocationBasedUserActivity) GrantOf(ctx contractapi.TransactionContextInterface, entityID string) (*SpectrumGrant, error) {
    return s.grantOf(ctx, entityID)
}

// ShareBandwidth sublets part of a grant.
//
// The holder cannot invent capacity: the grant was issued by this contract
// when the entity was admitted, and the check below is against that record
// rather than against anything the caller says it owns.
func (s *LocationBasedUserActivity) ShareBandwidth(ctx contractapi.TransactionContextInterface, from, to, hz, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot sublet to yourself")
    }
    amount, err := strconv.ParseInt(hz, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("hz must be a positive whole number, got %q", hz)
    }
    price := parseIntOr(priceMicro, 0)

    g, err := s.grantOf(ctx, from)
    if err != nil {
        return err
    }
    available := g.HeldHz - g.SubletHz
    if available < amount {
        return fmt.Errorf("%s holds %d Hz with %d already sublet, so only %d Hz is free",
            from, g.HeldHz, g.SubletHz, available)
    }

    recipient, err := s.grantOf(ctx, to)
    if err != nil {
        return err
    }
    if recipient.Cell == "" {
        recipient.Cell = g.Cell
    }
    if recipient.Cell != g.Cell {
        return fmt.Errorf("spectrum is only usable on the cell that issued it: %s holds %s, %s is on %s",
            from, g.Cell, to, recipient.Cell)
    }

    g.SubletHz += amount
    recipient.HeldHz += amount
    if err := s.saveGrant(ctx, g); err != nil {
        return err
    }
    if err := s.saveGrant(ctx, recipient); err != nil {
        return err
    }
    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

// ShareEnergy moves battery between entities.
//
// The budget is metered by this contract on every transmission, so what is
// moved here is a figure the contract itself produced.
func (s *LocationBasedUserActivity) ShareEnergy(ctx contractapi.TransactionContextInterface, from, to, microJ, priceMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if from == to {
        return fmt.Errorf("cannot share energy with yourself")
    }
    amount, err := strconv.ParseInt(microJ, 10, 64)
    if err != nil || amount <= 0 {
        return fmt.Errorf("microJ must be a positive whole number, got %q", microJ)
    }
    price := parseIntOr(priceMicro, 0)

    donor, err := s.energyOf(ctx, from, cfg)
    if err != nil {
        return err
    }
    if donor.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ, cannot share %d µJ",
            from, donor.RemainingMicroJ, amount)
    }
    receiver, err := s.energyOf(ctx, to, cfg)
    if err != nil {
        return err
    }

    donor.RemainingMicroJ -= amount
    receiver.RemainingMicroJ += amount
    if receiver.RemainingMicroJ > receiver.TotalMicroJ {
        receiver.TotalMicroJ = receiver.RemainingMicroJ
    }

    db, err := json.Marshal(donor)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+from, db); err != nil {
        return err
    }
    rb, err := json.Marshal(receiver)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(energyPrefix+to, rb); err != nil {
        return err
    }

    if price > 0 {
        if err := s.debit(ctx, to, price, cfg); err != nil {
            return err
        }
        return s.credit(ctx, from, price, cfg)
    }
    return nil
}

/* ── verifiable computation ────────────────────────────────────────────
   Nothing on a ledger can observe a processor, so compute cannot be
   reported — it has to be proven. The scheme is the one the mining
   literature uses, repurposed: the requester states a challenge and a
   difficulty, the worker searches for a nonce whose hash clears the
   threshold, and the contract confirms it with a single hash.

   The asymmetry is the whole mechanism. At 16 bits the worker averages
   65536 hashes; the contract does one. A worker cannot claim work it did
   not do, and the network pays nothing to check.                          */

func workHash(challenge, nonce string) uint32 {
    return mix32(fnv1a(challenge + "|" + nonce))
}

// meetsDifficulty reports whether the hash has at least bits leading zeros.
func meetsDifficulty(h uint32, bits int64) bool {
    if bits <= 0 {
        return true
    }
    if bits >= 32 {
        return h == 0
    }
    return h < (uint32(1) << uint(32-bits))
}

// PostTask advertises work and escrows the reward, so a worker who solves
// it cannot be left unpaid.
func (s *LocationBasedUserActivity) PostTask(ctx contractapi.TransactionContextInterface, taskID, requester, challenge, difficultyBits, rewardMicro string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if taskID == "" || requester == "" || challenge == "" {
        return fmt.Errorf("taskID, requester and challenge are all required")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("task %s already exists", taskID)
    }

    bits := parseIntOr(difficultyBits, 16)
    if bits < 1 || bits > maxDifficultyBits {
        return fmt.Errorf("difficultyBits must be between 1 and %d, got %d", maxDifficultyBits, bits)
    }
    reward := parseIntOr(rewardMicro, cfg.WorkReward)
    if reward <= 0 {
        return fmt.Errorf("reward must be positive, got %d", reward)
    }

    // Escrow: the requester pays now, the worker is paid on proof.
    if err := s.debit(ctx, requester, reward, cfg); err != nil {
        return fmt.Errorf("cannot escrow the reward: %v", err)
    }

    t := WorkTask{
        TaskID:         taskID,
        Requester:      requester,
        Challenge:      challenge,
        DifficultyBits: bits,
        RewardMicro:    reward,
        PostedAt:       txTimestamp(ctx),
    }
    b, err := json.Marshal(t)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+taskID, b)
}

// SubmitWork claims a task with a nonce. The proof is checked here; a wrong
// nonce is rejected and nothing is paid.
func (s *LocationBasedUserActivity) SubmitWork(ctx contractapi.TransactionContextInterface, taskID, worker, nonce string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return err
    }
    if b == nil {
        return fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return err
    }
    if t.Solved {
        return fmt.Errorf("task %s was already solved by %s", taskID, t.Worker)
    }
    if worker == "" {
        return fmt.Errorf("worker is required")
    }

    if !meetsDifficulty(workHash(t.Challenge, nonce), t.DifficultyBits) {
        return fmt.Errorf(
            "nonce %q does not clear %d bits for challenge %q",
            nonce, t.DifficultyBits, t.Challenge)
    }

    t.Solved = true
    t.Worker = worker
    t.Nonce = nonce
    t.SolvedAt = txTimestamp(ctx)
    tb, err := json.Marshal(t)
    if err != nil {
        return err
    }
    if err := ctx.GetStub().PutState(taskPrefix+taskID, tb); err != nil {
        return err
    }
    return s.credit(ctx, worker, t.RewardMicro, cfg)
}

// TaskOf reads a task.
func (s *LocationBasedUserActivity) TaskOf(ctx contractapi.TransactionContextInterface, taskID string) (*WorkTask, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + taskID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no task %s", taskID)
    }
    var t WorkTask
    if err := json.Unmarshal(b, &t); err != nil {
        return nil, err
    }
    return &t, nil
}

/* ── relaying ──────────────────────────────────────────────────────────
   The paper routes small-cell users through an SBS. The same idea works
   between entities: an edge device with a weak link sends through a
   neighbour that has a strong one.

   Both energy figures come from the propagation model, so neither party
   states its own saving. The relay is paid a share of what the edge entity
   avoided spending — capped so the deal is worthwhile for both.            */

func (s *LocationBasedUserActivity) RelayFor(ctx contractapi.TransactionContextInterface, dealID, edgeEntity, edgeX, edgeY, relayEntity, relayX, relayY string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    if dealID == "" || edgeEntity == "" || relayEntity == "" {
        return fmt.Errorf("dealID, edgeEntity and relayEntity are all required")
    }
    if edgeEntity == relayEntity {
        return fmt.Errorf("an entity cannot relay for itself")
    }
    existing, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return err
    }
    if existing != nil {
        return fmt.Errorf("deal %s already exists", dealID)
    }

    ex, err := parseCoord(edgeX)
    if err != nil {
        return err
    }
    ey, err := parseCoord(edgeY)
    if err != nil {
        return err
    }
    rx, err := parseCoord(relayX)
    if err != nil {
        return err
    }
    ry, err := parseCoord(relayY)
    if err != nil {
        return err
    }

    antennas, err := s.listAntennas(ctx)
    if err != nil {
        return err
    }
    edgeReports, _, err := s.evaluate(antennas, cfg, edgeEntity, ex, ey)
    if err != nil {
        return err
    }
    relayReports, _, err := s.evaluate(antennas, cfg, relayEntity, rx, ry)
    if err != nil {
        return err
    }
    edgeDirect := edgeReports[0]
    relayLink := relayReports[0]

    if edgeDirect.EnergyMicroJ < 0 || relayLink.EnergyMicroJ < 0 {
        return fmt.Errorf("neither path carries a usable rate")
    }
    if relayLink.SinrMilliDb <= edgeDirect.SinrMilliDb {
        return fmt.Errorf(
            "relaying gains nothing: %s sees %d mdB, %s sees %d mdB",
            relayEntity, relayLink.SinrMilliDb, edgeEntity, edgeDirect.SinrMilliDb)
    }

    // The device-to-device hop is short, so it costs far less than the
    // direct uplink. Its rate is derived the same way as any other link.
    d2dDist := DistanceM(ex, ey, rx, ry)
    d2dPl := PathLossMilliDb(d2dDist, defaultFreqMHz, cfg.PathLossExponentMilli)
    d2dRssi := RssiMilliDbm(cfg.TxPowerMilliDbm, 0, d2dPl, 0)
    d2dSinr := SinrMilliDb(d2dRssi, []int64{},
        NoiseFloorMilliDbm(defaultBandwidthHz, cfg.NoiseFigureMilliDb))
    d2dRate := ShannonBps(cfg.RequestHz, d2dSinr)
    d2dEnergy := TransmitEnergyMicroJ(cfg.TxPowerMilliDbm, cfg.PayloadBits, d2dRate)
    if d2dEnergy < 0 {
        return fmt.Errorf("the device-to-device hop carries no usable rate over %d m", d2dDist)
    }

    saved := edgeDirect.EnergyMicroJ - d2dEnergy
    if saved <= relayLink.EnergyMicroJ {
        return fmt.Errorf(
            "relaying costs more than it saves: %d µJ saved against %d µJ spent by the relay",
            saved, relayLink.EnergyMicroJ)
    }

    // The relay recovers its own cost plus a share of the surplus.
    surplus := saved - relayLink.EnergyMicroJ
    pay := ((relayLink.EnergyMicroJ + (surplus*cfg.RelayShareHundred)/100) * cfg.PriceScale) / 1000

    if err := s.debit(ctx, edgeEntity, pay, cfg); err != nil {
        return fmt.Errorf("%s cannot pay the relay: %v", edgeEntity, err)
    }
    if err := s.credit(ctx, relayEntity, pay, cfg); err != nil {
        return err
    }

    // Both parties spend the energy the model says they spend.
    if cfg.TrackEnergy {
        if err := s.spendEnergy(ctx, edgeEntity, d2dEnergy, cfg); err != nil {
            return err
        }
        if err := s.spendEnergy(ctx, relayEntity, relayLink.EnergyMicroJ, cfg); err != nil {
            return err
        }
    }

    deal := RelayDeal{
        DealID:        dealID,
        EdgeEntity:    edgeEntity,
        RelayEntity:   relayEntity,
        DirectEnergy:  edgeDirect.EnergyMicroJ,
        RelayedEnergy: d2dEnergy,
        SavedMicroJ:   saved,
        PaidMicro:     pay,
        Timestamp:     txTimestamp(ctx),
    }
    db, err := json.Marshal(deal)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(taskPrefix+"relay:"+dealID, db)
}

// spendEnergy debits a battery, refusing rather than going negative.
func (s *LocationBasedUserActivity) spendEnergy(ctx contractapi.TransactionContextInterface, entityID string, amount int64, cfg *NetworkConfig) error {
    b, err := s.energyOf(ctx, entityID, cfg)
    if err != nil {
        return err
    }
    if b.RemainingMicroJ < amount {
        return fmt.Errorf("%s has %d µJ but the hop costs %d µJ",
            entityID, b.RemainingMicroJ, amount)
    }
    b.RemainingMicroJ -= amount
    b.SpentMicroJ += amount
    b.TxCount++
    b.Timestamp = txTimestamp(ctx)
    bb, err := json.Marshal(b)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(energyPrefix+entityID, bb)
}

// RelayOf reads a deal.
func (s *LocationBasedUserActivity) RelayOf(ctx contractapi.TransactionContextInterface, dealID string) (*RelayDeal, error) {
    b, err := ctx.GetStub().GetState(taskPrefix + "relay:" + dealID)
    if err != nil {
        return nil, err
    }
    if b == nil {
        return nil, fmt.Errorf("no relay deal %s", dealID)
    }
    var d RelayDeal
    if err := json.Unmarshal(b, &d); err != nil {
        return nil, err
    }
    return &d, nil
}

// SetMarket configures the market.
//   stripes     sub-keys per account; 1 is the naive layout, higher spreads
//               the contention a payee otherwise concentrates
//   priceScale  micro-tokens per 1000 µJ of value
//   relayShare  the relay's cut of the surplus, in percent
//   workReward  default reward for a posted task
func (s *LocationBasedUserActivity) SetMarket(ctx contractapi.TransactionContextInterface, stripes, priceScale, relayShare, workReward string) error {
    cfg, err := s.loadConfig(ctx)
    if err != nil {
        return err
    }
    cfg.Stripes = parseIntOr(stripes, cfg.Stripes)
    cfg.PriceScale = parseIntOr(priceScale, cfg.PriceScale)
    cfg.RelayShareHundred = parseIntOr(relayShare, cfg.RelayShareHundred)
    cfg.WorkReward = parseIntOr(workReward, cfg.WorkReward)

    if cfg.Stripes < 1 || cfg.Stripes > 256 {
        return fmt.Errorf("stripes must be between 1 and 256, got %d", cfg.Stripes)
    }
    if cfg.RelayShareHundred < 0 || cfg.RelayShareHundred > 100 {
        return fmt.Errorf("relayShare must be a percentage, got %d", cfg.RelayShareHundred)
    }
    cfgJSON, err := json.Marshal(cfg)
    if err != nil {
        return err
    }
    return ctx.GetStub().PutState(configKey, cfgJSON)
}

const (
	radioQ         = 16
	radioOne       = int64(1) << radioQ // 65536
	dbOffsetMilli  = int64(150000)      // 150 dB
	log2_10Over10  = int64(3322)        // log2(10)/10 × 10000
	log2_10Scaled  = int64(33219)       // log2(10) × 10000
	noiseDensity   = int64(-174000)     // −174 dBm/Hz
	freeSpaceConst = int64(27600)       // 27.6 dB anchor at 1 m, 1 GHz
)

// 2^(1/2^(i+1)) in Q16 — used to build any fractional power of two.
var halfPowers = [10]int64{
	92682, 77936, 71468, 68438, 66971, 66250, 65892, 65714, 65625, 65580,
}

// floorDiv divides rounding toward negative infinity. Go truncates toward
// zero, which splits negative exponents wrongly in exp2Q16.
func floorDiv(a, b int64) int64 {
	q := a / b
	if a%b != 0 && (a < 0) != (b < 0) {
		q--
	}
	return q
}

// Isqrt is the exact integer square root (floor), by Newton's method.
func Isqrt(n int64) int64 {
	if n < 2 {
		if n < 0 {
			return 0
		}
		return n
	}
	x := n
	y := (x + 1) / 2
	for y < x {
		x = y
		y = (x + n/x) / 2
	}
	return x
}

// Log2Milli returns 1000·log2(x). The integer part is the bit length; the
// fraction comes from repeated squaring, which is exact in integers.
func Log2Milli(x int64) int64 {
	if x <= 0 {
		return -(int64(1) << 30)
	}
	k := int64(0)
	for v := x; v >= 2; v >>= 1 {
		k++
	}
	var m int64
	if k <= radioQ {
		m = x << uint(radioQ-int(k))
	} else {
		m = x >> uint(int(k)-radioQ)
	}
	frac := int64(0)
	for i := 0; i < 20; i++ {
		m = (m * m) / radioOne
		frac <<= 1
		if m >= 2*radioOne {
			m >>= 1
			frac |= 1
		}
	}
	return k*1000 + (frac*1000)>>20
}

// Log10Milli returns 1000·log10(x).
func Log10Milli(x int64) int64 {
	return (Log2Milli(x) * 10000) / log2_10Scaled
}

// exp2FracQ16 computes 2^(f/1000) in Q16 for f in [0,1000).
// The fraction is converted to ten binary bits first: dividing 1000 by
// powers of two truncates, and that error compounds across the ten steps.
func exp2FracQ16(f int64) int64 {
	r := radioOne
	bits := (f * 1024) / 1000 // 0..1023
	for i := 0; i < 10; i++ {
		if bits&(int64(1)<<uint(9-i)) != 0 {
			r = (r * halfPowers[i]) / radioOne
		}
	}
	return r
}

// exp2Q16 computes 2^(milli/1000) in Q16, saturating rather than wrapping.
func exp2Q16(milli int64) int64 {
	k := floorDiv(milli, 1000)
	f := milli - k*1000 // always 0..999
	frac := exp2FracQ16(f)
	switch {
	case k >= 46:
		return int64(1) << 62
	case k >= 0:
		return frac << uint(k)
	case k <= -17:
		return 0 // below Q16 resolution
	default:
		return frac >> uint(-k)
	}
}

// LinearQ16 converts milli-dBm to offset linear power.
func LinearQ16(mdbm int64) int64 {
	return exp2Q16(floorDiv((mdbm+dbOffsetMilli)*log2_10Over10, 10000))
}

// DbmFromLinearQ16 is the inverse of LinearQ16.
func DbmFromLinearQ16(lin int64) int64 {
	if lin <= 0 {
		return -dbOffsetMilli
	}
	l2 := Log2Milli(lin) - radioQ*1000
	return (l2*10000)/log2_10Over10 - dbOffsetMilli
}

// ── deterministic pseudo-randomness ─────────────────────────────────────
// Chaincode may not call rand or read a clock, so every "random" quantity is
// derived from the identifiers plus a scenario seed supplied in the
// transaction. Same inputs, same value, on every peer and on every replay.

func fnv1a(s string) uint32 {
	h := uint32(0x811c9dc5)
	for i := 0; i < len(s); i++ {
		h ^= uint32(s[i])
		h *= 0x01000193
	}
	return h
}

// mix32 is the Murmur3 finalizer. FNV alone mixes poorly between strings
// differing only in their last character; without this step the four draws
// below correlate at −0.42 and the spread collapses to 64% of sigma.
func mix32(x uint32) uint32 {
	x ^= x >> 16
	x *= 0x85ebca6b
	x ^= x >> 13
	x *= 0xc2b2ae35
	x ^= x >> 16
	return x
}

func hashUniform(seed, a, b string, i int) int64 {
	h := fnv1a(seed + "|" + a + "|" + b)
	return int64(mix32(h+uint32(i)*0x9e3779b9) % 1000)
}

// ShadowingMilliDb returns a zero-mean fade with the requested sigma.
// Four uniforms are summed (Irwin–Hall); their sum has sd = 577.4, so the
// division by 577 gives unit variance before scaling.
func ShadowingMilliDb(seed, a, b string, sigmaMilliDb int64) int64 {
	acc := int64(0)
	for i := 0; i < 4; i++ {
		acc += hashUniform(seed, a, b, i)
	}
	return ((acc - 2000) * sigmaMilliDb) / 577
}

// PlaceOnGrid maps an identifier and seed to a deterministic position inside
// a square of the given size — the scenario "random" placement.
func PlaceOnGrid(seed, id string, sizeM int64) (int64, int64) {
	h := fnv1a(seed + "#" + id)
	x := int64(mix32(h)) % sizeM
	y := int64(mix32(h^0x5bf03635)) % sizeM
	return x, y
}

// ── radio model ─────────────────────────────────────────────────────────

// DistanceM is the Euclidean distance in whole metres.
func DistanceM(x1, y1, x2, y2 int64) int64 {
	dx, dy := x1-x2, y1-y2
	return Isqrt(dx*dx + dy*dy)
}

// PathLossMilliDb uses the log-distance model with a free-space anchor:
//
//	PL(d) = 32.4 + 20·log10(f_GHz) + 10·n·log10(d)
//	      = 20·log10(f_MHz) + 10·n·log10(d) − 27.6
func PathLossMilliDb(distM, freqMHz, exponentMilli int64) int64 {
	d := distM
	if d < 1 {
		d = 1 // the model diverges at zero
	}
	return 20*Log10Milli(freqMHz) +
		(exponentMilli*Log10Milli(d))/10 -
		freeSpaceConst
}

// NoiseFloorMilliDbm is thermal noise plus the receiver noise figure:
// −174 dBm/Hz + 10·log10(BW) + NF.
func NoiseFloorMilliDbm(bandwidthHz, noiseFigureMilliDb int64) int64 {
	return noiseDensity + 10*Log10Milli(bandwidthHz) + noiseFigureMilliDb
}

// RssiMilliDbm is received power after antenna gain, path loss and fading.
func RssiMilliDbm(txPowerMilliDbm, gainMilliDb, plMilliDb, shadowMilliDb int64) int64 {
	return txPowerMilliDbm + gainMilliDb - plMilliDb - shadowMilliDb
}

// SinrMilliDb sums interference and noise in the linear domain, then returns
// the ratio in dB. This is why the linear conversion has to exist at all:
// powers add linearly, not logarithmically.
func SinrMilliDb(signalMdbm int64, interferers []int64, noiseMdbm int64) int64 {
	denom := LinearQ16(noiseMdbm)
	for _, i := range interferers {
		denom += LinearQ16(i)
	}
	return signalMdbm - DbmFromLinearQ16(denom)
}

// ShannonBps is C = BW·log2(1 + SINR_linear) in bits per second.
// SINR is a ratio, so it converts with no dBm offset.
func ShannonBps(bandwidthHz, sinrMdb int64) int64 {
	ratioQ16 := exp2Q16(floorDiv(sinrMdb*log2_10Over10, 10000))
	spectral := Log2Milli(radioOne+ratioQ16) - radioQ*1000
	if spectral <= 0 {
		return 0
	}
	return (bandwidthHz * spectral) / 1000
}

/* ── power, time and energy ──────────────────────────────────────────
   The paper this follows models uplink cost as transmit time and the
   energy that time consumes: t = D/R and e = P·D/R, with a budget
   constraint e ≤ E_max. Both need transmit power as a linear quantity,
   which is what MicroWattFromMilliDbm provides.

   Units: power µW, time µs, energy µJ. One mW for one µs is one nJ, so
   µW × µs lands in picojoules and the divisor below converts to µJ.
   int64 holds a 5 J budget (5×10⁶ µJ) with room to spare.                */

// MicroWattFromMilliDbm converts milli-dBm to microwatts.
// 23 dBm → 199526 µW (the reference value; this returns within 0.2%).
func MicroWattFromMilliDbm(mdbm int64) int64 {
    // µW = 10^(dBm/10) × 1000, so the log2 exponent is (dBm/10 + 3)·log2(10)
    e := floorDiv((mdbm+30000)*log2_10Over10, 10000)
    return exp2Q16(e) >> radioQ
}

// TransmitTimeMicroS returns how long dataBits takes at rateBps.
func TransmitTimeMicroS(dataBits, rateBps int64) int64 {
    if rateBps <= 0 {
        return -1 // no usable link
    }
    return (dataBits * 1000000) / rateBps
}

// TransmitEnergyMicroJ is P × t, the energy that transmission costs.
func TransmitEnergyMicroJ(txPowerMilliDbm, dataBits, rateBps int64) int64 {
    t := TransmitTimeMicroS(dataBits, rateBps)
    if t < 0 {
        return -1
    }
    // µW × µs = pJ; divide by 10^6 for µJ
    return (MicroWattFromMilliDbm(txPowerMilliDbm) * t) / 1000000
}

func main() {
    chaincode, err := contractapi.NewChaincode(new(LocationBasedUserActivity))
    if err != nil {
        fmt.Printf("Error creating chaincode: %v\n", err)
        return
    }
    if err := chaincode.Start(); err != nil {
        fmt.Printf("Error starting chaincode: %v\n", err)
    }
}
CHAINCODE_EOF
            ;;
        *)
            echo "No template for $contract" >&2
            exit 1
            ;;
    esac

    (
      cd chaincode/$contract
      if [ ! -f go.mod ]; then
          go mod init $contract >/dev/null 2>&1
      fi
      go mod edit -require=github.com/hyperledger/fabric-contract-api-go@v1.2.1
      go mod tidy >/dev/null 2>&1
      go mod vendor >/dev/null 2>&1
    )
done

echo "Regenerated ${#contracts[@]} of ${#ALL_CONTRACTS[@]} location-aware contracts in $SCRIPT_DIR/chaincode"
for contract in "${contracts[@]}"; do
    if [ -f "chaincode/$contract/chaincode.go" ]; then
        echo " - $contract: OK"
    else
        echo " - $contract: Failed"
    fi
done
